quests[10582] = { id = 10582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minions of the Shadow Council", description = "<Ewan listens to you recount the events at Legion Hold, nodding.>\n\nThat puts our observations into perspective. We've caught glimpses of them launching infernals in the direction of the hold, but haven't been able to find much more than that.\n\nThe Shadow Council has the Deathforge sealed tighter than a new keg o' thunderbrew. The first thing you'll need to do is crack some skulls so you can get in there and poke around. Start eliminating the Shadow Council guarding the entrance to the Deathforge!", sourceObjective = "Stormer Ewan Wildwing at the Deathforge Tower wants you to kill 10 Deathforge Guardians and 5 Deathforge Summoners.", progress = "Have you cleared a way into the Deathforge yet?", completion = "I wish I could've been out there with you! I've been itching to put my hammer to use, but my mission is to observe, not to kill.\n\nNow that you've punched a hole in their defenses, let's get to work on shutting down production in the Deathforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[10583] = { id = 10583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Flanis", description = "Wing Commander Nuainn originally sent three of us out here to keep watch over the Deathforge and to gather information. Flanis Swiftwing volunteered to try to infiltrate the Deathforge, but we haven't heard anything from him in days.\n\nI fear the worst, {name}. Flanis is a skilled scout, but if he's gotten in over his head, we have no way of knowing. Search the Deathforge for him and recover any information or items he might have collected.", sourceObjective = "Stormer Ewan Wildwing at Deathforge Tower wants you to search the Deathforge for Flanis Swiftwing and recover Flanis's Pack.", progress = "Did you find any sign of Flanis in the Deathforge?", completion = "<Ewan shakes his head as he accepts the pack from you>\n\nI don't think Flanis realized how heavily guarded the Deathforge would be. Now that we know what's really going on there, I don't blame them. I just wish Flanis had known that when he went in.\n\nI can only hope there's something here that will help us shut down the Deathforge once and for all.", sourceObjectiveStatus = "unverified-source-field" }
quests[10584] = { id = 10584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Picking Up Some Power Converters", description = "Those dumb ogres at the Bladespire Outpost to the north have been raiding our power converters!  And you're going to get them back for me, sort of.\n\nNo doubt, with their big, clumsy hands, the ogres have damaged the converters.  So, what I want you to do is release the energy from them and then use this protovoltaic magneto collector on the resultant electromental to encase it.\n\nIt'll likely be sore with you, so you'll need to 'kill' it while it's contained in the magneto sphere.", sourceObjective = "Use the Protovoltaic Magneto Collector to collect 5 Electromentals.", progress = "This line of research we have going with the electromentals is exciting!  Just think of it... intelligent electrical creatures that we can create at will and that will follow our every instruction!\n\nWhat could possibly go wrong?", completion = "Excellent!  With all of this power that you've recovered we'll be able to keep the machinery running for a little while, anyway.\n\nThe Zephyrium Capacitorium is a real pig when it comes to power consumption!\n\nI hope dealing with those electromentals wasn't too difficult.  I have something else in mind for you to do, and I have a feeling that it's going to be a little more dangerous.", sourceObjectiveStatus = "unverified-source-field" }
quests[10585] = { id = 10585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Summoning Chamber", description = "In order for the Shadow Council to construct infernals as quickly as they're being used, they must have an area dedicated to summoning the corrupted elementals that serve as the souls of the creatures.\n\nThe summoning chamber is likely to be found below ground, near a pool of fouled water or lava. Locate the summoning chamber within the Deathforge and find a way to end their summoning ritual. The mo'arg involved in making the infernals may carry a tool that will help disrupt the summoner's magics.", sourceObjective = "Obtain an Elemental Displacer from a Deathforge Smith or Deathforge Tinkerer and use it to disrupt the ritual in the summoning  chamber. Report to Stormer Ewan Wildwing at the Deathforge Tower when you've completed your task.", progress = "We cannot afford to let their production continue. Have you put an end to the summoning ritual?", completion = "Well done, {name}. Disrupting the Shadow Council's summoning puts us one step closer to shutting down the Deathforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[10586] = { id = 10586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Down the Warbringer!", description = "We've made a lot of progress against the Shadow Council's operations at the Deathforge, but if we're to truly be triumphant, we'll need to defeat the Legion's overseer there.\n\nI found a key among the items in Flanis's pack. I'm certain it will prove useful in tracking down this Warbringer Razuun you observed at Legion Hold.\n\nAfter you've hunted down and dealt with Warbringer Razuun, report directly to Wing Commander Nuainn. He'll want to know immediately!", sourceObjective = "Defeat Warbringer Razuun, recover Razuun's Orders, and report to Wing Commander Nuainn at Wildhammer Stronghold.", progress = "What news do you bring from the Deathforge?", completion = "<You make your report to the wing commander and hand over the captured orders.>\n\nDefeating Warbringer Razuun should've meant the end of our troubles with the Legion, but these orders outline a much larger plan that I had anticipated. I fear that more remains to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[10587] = { id = 10587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karabor Training Grounds", description = "Our scouts have reported a massive influx of Sunfury blood elf recruits heading to the Ruins of Karabor.  Normally this would represent a purely military threat, however we believe something else is amiss.\n\nDescriptions of their attire and fighting style are suspiciously close to that of Illidan himself.  I do not want to become alarmed without good reason, so I would like you to go there and bring me back their weapons.  We will then determine whether my fears are unfounded or not.", sourceObjective = "Exarch Onaala at the Altar of Sha'tar wants you to obtain 8 Sunfury Glaives from Demon Hunter Supplicants and Demon Hunter Initiates at the Ruins of Karabor, southeast of the Altar of Sha'tar.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Have you completed the task I asked of you, {name}?", completion = "Let's take a closer look at these weapons, {name}.  Hmmm... this is rather unsettling.", sourceObjectiveStatus = "unverified-source-field" }
quests[10588] = { id = 10588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cipher of Damnation", description = "How many times has this spell been used in the history of our worlds? Undoubtedly, its power for destruction is unparalleled.\n\nWhat you must do now is take the cipher, now made whole, and read from it at the Altar of Damnation - where the memory of Gul'dan stands.\n\nWhat you will see once the words are uttered are the memories left imprinted upon the land. Stand your ground and await the coming of Cyrukh.\n\nYou must be victorious, {name}. This land cannot withstand another shattering.", sourceObjective = "Use the Cipher of Damnation at the Altar of Damnation to summon Cyrukh the Firelord.\n\nDestroy Cyrukh the Firelord and then speak with Earthmender Torlok, also found at the Altar of Damnation.", progress = "Is it done?", completion = "<Earthmender Torlok takes the Cipher of Damnation from you.>\n\nYou have done as the elements asked. For that, we are grateful. While you will be rewarded, trouble still looms. The spirits of fire are in turmoil. A claim has been made. the Cipher of Damnation is known by another.\n\nIt is cryptic, I know, but that is all that the spirits would have me know. That and this symbol...\n\n<Earthmender Torlok turns around and points to the sky.>\n\nWhat could it mean?", sourceObjectiveStatus = "unverified-source-field" }
quests[10589] = { id = 10589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaining Access", description = "According to Razuun's orders, the massive infernal staging area is called Invasion Point: Cataclysm and it's nestled in the northern mountains. The only way to reach it is by using a teleporter located at Legion Hold.\n\nCertain members of the Legion host carry devices allowing them to activate the teleporters. You must capture one of these devices to win access to the teleporter. Slaughter all of the demons if you must, but you can't afford to return empty-handed.", sourceObjective = "Bring a Legion Teleporter Control to Wing Commander Nuainn at Wildhammer Stronghold. The Mo'arg Weaponsmiths at Legion Hold are known to carry the devices.", progress = "We must find a way to destroy the rest of those infernals, {name}. We've come far, but failure could still cost us everything.", completion = "Let me see if I can find out how this works...", sourceObjectiveStatus = "unverified-source-field" }
quests[10590] = { id = 10590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prove Your Hatred", description = "It is time you remembered history that should not be forgotten... the slaughter of our people by Arthas and his Scourge army.\n\nVengeance on the Scourge is the only way to ease your pain.  It is unfortunate they are not susceptible to fear and pain.  Only their utter destruction will bring you even a shred of satisfaction.\n\nSpeak with Argent Officer Garush for knowledge of scourgestones and how to obtain them -- I will need to see many of them as proof of your commitment before we speak again.", sourceObjective = "Mehlar Dawnblade at the Bulwark wants you to bring him 20 Minion's Scourgestones.", progress = "Have the Scourge crumbled beneath your weapon?", completion = "Very good, {name}.  Perhaps you have a taste for revenge after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[10592] = { id = 10592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wisdom of the Banshee Queen", description = "The scourgestones are weak when separated from the skeletal grasp that once held them.  Simply holding them in my hands has caused them to fracture and break.\n\n<Mehlar crushes the scourgestones into a pile of rubble.>\n\nTake these fragments to the Banshee Queen, Lady Sylvanas Windrunner, at her throne in Undercity.  With her lies the knowledge to turn these remains into a weapon against the Scourge.", sourceObjective = "Bring the Scourgestone Fragments to Lady Sylvanas Windrunner in Undercity.", progress = "Do you have something for me, {race}?", completion = "These stones carry a taint I do not wish to remember, but one I cannot forget.  You try my patience dangerously by bringing these to me.\n\nHowever, it is clear your heart seeks the same vengeance as I, and I will aid you with instruction.", sourceObjectiveStatus = "unverified-source-field" }
quests[10593] = { id = 10593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Evil", description = "If you wish to turn these stones into a weapon to fight the Scourge, you must acquire something equally vile to fortify them.\n\nAn ancient evil lies hidden at the bottom of the Temple of Atal'Hakkar in the Swamp of Sorrows.  Release the creature there and destroy him, taking only a small part of his body back to Mehlar Dawnblade.  My guards will deliver the scourgestone fragments to Mehlar.", sourceObjective = "Unlock the secrets of the Temple of Atal'Hakkar to release Atal'alarion and recover the Putrid Vine from his flesh. Return to Mehlar at the Bulwark when you have done this.", progress = "Given that you are alive, I can only surmise you were lucky enough to receive wisdom rather than death from Lady Sylvanas.", completion = "The Banshee Queen has guided you well.  This is precisely what I need to combine the fragments.\n\n<Mehlar watches as the vine interweaves through the fragments, binding them together.>\n\nThere!  Scourgebane, I shall call it.  Be wary when you use it, for it serves you against its will.", sourceObjectiveStatus = "unverified-source-field" }
quests[10594] = { id = 10594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gauging the Resonant Frequency", description = "Take these scanners to the Singing Ridge.  By dropping them in a pattern on the ground, you will create overlapping fields that will read the amplitude of the crystals.  Stand amidst them in such a way that you're in five oscillation fields and I'll have the information that I need!\n\nYour scanners will even work with those that others drop.\n\nOh, and it's likely that a rift will be formed!  I have no idea what, if anything, will come out of it, but be prepared for the worst.", sourceObjective = "Place the Oscillating Frequency Scanners in such a way that when you stand amongst them, you are hit by 5 overlapping Oscillation fields.", progress = "Well, do you have the measurements from the singing crystals that I asked for?", completion = "Oh, this is extraordinary!  I had no idea... it's almost as if those crystals are alive.\n\nI wonder if there's some sort of symbiotic relationship between them and the nether drakes?\n\nThank you, thank you!  You must accept a little something from my collection of odds and ends that I wouldn't be caught dead wearing.\n\nOne of them might look good on you, though.", sourceObjectiveStatus = "unverified-source-field" }
quests[10595] = { id = 10595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besieged!", description = "<Gulmok looks to the sky.>\n\nOur scouts are putting up a good fight, but the infernals keep coming!\n\nFrom their base of Legion Hold to the southwest, the demons bombard us with impunity! Even the elite Kor'kron guard cannot hold them off forever.\n\nI'm drafting every able-bodied {race} to do their part in defense of Shadowmoon Village. This is no game, {class}. The survival of the village is at stake. Do your duty to the Horde, and join the fray!", sourceObjective = "Blood Guard Gulmok outside of Shadowmoon Village, wants you to kill 10 Infernal Attackers.", completion = "I'm impressed that you managed to survive the carnage. You just might be the person we need for a dangerous mission.", sourceObjectiveStatus = "unverified-source-field" }
quests[10596] = { id = 10596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Legion Hold", description = "The fortress of Legion Hold is your target. You'll have no reinforcements, so a frontal attack is out of the question.\n\nWhat little information we have shows that the Legion stocks and prepares its infernals at the hold. With the help of a disguise I'll give you, you must sneak into Legion Hold and discover their plans.\n\nYour best hope is to intercept or overhear communication between their commanders.", sourceObjective = "Make your way to Legion Hold, locate the Legion Communication Device, and learn about the Legion's plans while in disguise. Return to Blood Guard Gulmok at Shadowmoon Village when you've completed your mission.", progress = "What did you discover?", completion = "<Blood Guard Gulmok listens to your report, growing more alarmed with each sentence.>\n\nWhat do you mean they're going to step up the bombardment? We can't allow that to happen. Get back out there and take care of it while there's something left of Shadowmoon Village!", sourceObjectiveStatus = "unverified-source-field" }
quests[10597] = { id = 10597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting Up the Bomb", description = "We can't allow the Legion to trample us on their march to Black Temple.\n\nFind a way to destroy the infernals they intend to use against us. That's not a request, {name}; it's an order.\n\nThe Fetid Pool near Legion Hold holds an old fel reaver power core you could use as the basis for a kind of fel bomb. Search the other wreckage near the fel reaver for a section of armor plating. You should be able to make a bomb powerful enough to take out those infernals and give the hold a nice shake!", sourceObjective = "Obtain a Fel Reaver Power Core and a Fel Reaver Armor Plate, then bring them to Blood Guard Gulmok at Shadowmoon Village.", progress = "<You hand the materials to Gulmok.>", completion = "<Gulmok slips the power core inside of the casing, then seals it.>\n\nThat should do the trick. I wouldn't want to be in the hold when that thing goes off.", sourceObjectiveStatus = "unverified-source-field" }
quests[10598] = { id = 10598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blast the Infernals!", description = "The device we've assembled won't win any beauty contests, but it should be capable of destroying the infernals amassed at Legion Hold. Judging from what the fel reaver power core's energy did to the Fetid Pool, it holds a respectable amount of explosive power.\n\nIf you set the device off in the middle of the green glyph at the hold, it should be in range to hit all of the infernals.", sourceObjective = "Use the Fel Bomb while standing on the green glyph in Legion Hold to destroy the infernals, then report to Blood Guard Gulmok at Shadowmoon Village.", progress = "Have you found a way to destroy the Legion's infernal stockpile?", completion = "<Gulmok nods grimly.>\n\nThis is no time for celebration, {name}. We're not out of the fire yet. I've got new orders for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10599] = { id = 10599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deathforge", description = "While you were taking care of the infernals at Legion Hold, I've been going over your reports. We've got no reason to believe the Legion lied about what's going on at the Deathforge. They're really cranking out infernals down there, so I've dispatched a scouting party to keep watch over it.\n\nIf we don't shut down the Deathforge, they'll rebuild the infernal stockpile that you destroyed at Legion Hold.\n\nReport to Scout Zagran atop Slag Watch, to the southeast of here and overlooking the Deathforge.", sourceObjective = "Report to Scout Zagran at Slag Watch.", completion = "<The orc nods.>\n\nIt'll be good to have the backup. We've gathered some preliminary information on what the Shadow Council is up to in there, but it's time for the hammer to fall.", sourceObjectiveStatus = "unverified-source-field" }
quests[10600] = { id = 10600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minions of the Shadow Council", description = "<Zagran listens to you recount the events at Legion Hold, nodding.>\n\nThat fills in the gaps we've seen. We've caught glimpses of them launching infernals in the direction of the hold, but haven't been able to find much more than that.\n\nThe Shadow Council has the forge pretty much locked down. Looks like you're going to need to fight your way in. Start eliminating the Shadow Council guarding the entrance to the Deathforge!", sourceObjective = "Scout Zagran at Slag Watch wants you to kill 10 Deathforge Guardians and 5 Deathforge Summoners.", completion = "I'd've been down there cracking skulls myself, but I'm under strict orders not to engage the enemy.\n\n<The scout grumbles, doing a fair imitation of Blood Guard Gulmok's voice.>\n\nLet's get to work on shutting down production in there.", sourceObjectiveStatus = "unverified-source-field" }
quests[10601] = { id = 10601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Kagrosh", description = "The scouting party originally had three members. Unfortunately, Kagrosh decided he wanted to be a hero.\n\nHe descended into the Deathforge and we haven't heard from him since.\n\nIn all likelihood, the fool's gone and gotten himself killed. The Shadow Council members aren't idiots and Kagrosh wasn't exactly strong in the subtlety department, if you know what I mean. Keep an eye out for him in the Deathforge and recover any information or items he might have collected.", sourceObjective = "Scout Zagran at Slag Watch wants you to search the Deathforge for Kagrosh and recover Kagrosh's Pack.", progress = "Did you find any sign of Kagrosh in the Deathforge?", completion = "<Zagran shakes his head as he accepts the pack from you>\n\nI told you he was a fool. I hope there's something in here that justifies the time you spent searching for him.", sourceObjectiveStatus = "unverified-source-field" }
quests[10602] = { id = 10602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Summoning Chamber", description = "In order to churn out infernals as quickly as the Deathforge seems to, they must have an area dedicated to summoning the elementals that form the core of the infernals.\n\nThe summoning chamber is likely to be found below ground, near a pool of fouled water or lava. Locate the summoning chamber within the Deathforge and find a way to end their summoning ritual. The mo'arg involved in making the infernals may carry a tool that will help disrupt the summoner's magics.", sourceObjective = "Obtain an Elemental Displacer from a Deathforge Smith or Deathforge Tinkerer and use it to disrupt the ritual in the summoning chamber. Report to Scout Zagran at Slag Watch when you've completed your task.", progress = "We cannot afford to let their production continue. Have you put an end to the summoning ritual?", completion = "Good, we're making progress. That puts us one step closer to shutting down this facility and returning safely to Shadowmoon Village.", sourceObjectiveStatus = "unverified-source-field" }
quests[10603] = { id = 10603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Down the Warbringer!", description = "We've made a lot of progress against the Shadow Council here at the Deathforge, but now it's time to finish the job.\n\nI found a key among the items in Kagrosh's pack. At least he accomplished something before they got to him.\n\nThe key should help you to track down this Warbringer Razuun you observed at Legion Hold.\n\nAfter you've hunted down and dealt with Warbringer Razuun, report directly to Blood Guard Gulmok. We must not keep him waiting.", sourceObjective = "Defeat Warbringer Razuun, recover Razuun's Orders, and report to Blood Guard Gulmok at Shadowmoon Village.", progress = "What news do you bring from the Deathforge?", completion = "<You make your report to the blood guard and hand over the captured orders.>\n\nGood work, {name}, but don't go thinking you'll be getting any ribbons for it. Let the night elves decorate their pretty little uniforms if they wish. Real warriors share tales of battle over a mug of ale.", sourceObjectiveStatus = "unverified-source-field" }
quests[10604] = { id = 10604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaining Access", description = "According to Razuun's orders, the massive infernal staging area is called Invasion Point: Cataclysm and it's located in the mountains behind our village! The only way to reach it is by using a teleporter at Legion Hold.\n\nCertain Legion minions carry a device allowing them to use the teleporter. You must capture one of these devices to win access to the teleporter. Slaughter all of the demons if you must, but you can't afford to return empty-handed. Do not delay; the enemy is perilously close.", sourceObjective = "Bring a Legion Teleporter Control to Blood Guard Gulmok at Shadowmoon Village. The Mo'arg Weaponsmiths at Legion Hold are known to carry the devices.", progress = "A Legion presence in our midst is intolerable! We must find a way to deal with it before they can renew their assault.", completion = "At last, we have a means with which to drive the Legion from Shadowmoon!", sourceObjectiveStatus = "unverified-source-field" }
quests[10605] = { id = 10605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carendin Summons", description = "You have a hungry look about you, {name}.  Perhaps it is time you advanced your training.\n\nTravel to Undercity and speak with Carendin Halgar, the old bag of bones knows a trick or two you might find useful.", sourceObjective = "Speak with Carendin Halgar in Undercity.", completion = "Ah, yet another power hungry initiate.  Wonderful!\n\nWouldn't be much of a {class} if you didn't thirst for power, now would you boy?  Let's get on with it.", sourceObjectiveStatus = "unverified-source-field" }
quests[10606] = { id = 10606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Art of Fel Reaver Maintenance", description = "The best way to destroy the rest of the Legion's supplies is to use their own weapons against them. I've been working on a rig that will let you take control of one of those Fel Reaver Sentinels below.\n\nThere are a couple things I need to work out, yet. For that, I'll need the manual that Doctor Gutrick keeps locked in a chest at the bottom of the ramp. He probably won't give up the key without a fight, so you'll need to capture it. Bring the fel reaver manual back to me and I'll do the rest!", sourceObjective = "Kill Doctor Gutrick and obtain the Doctor's Key. Use the key to open the Doctor's Strongbox to retrieve The Art of Fel Reaver Maintenance and deliver the book to Plexi at Invasion Point: Cataclysm.", progress = "Did you get that manual?", completion = "Ah, this is exactly what we'll need. I'd never accuse the Legion of producing anything resembling literature, but it gets the job done.", sourceObjectiveStatus = "unverified-source-field" }
quests[10607] = { id = 10607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers of the Raven God", description = "At Grishnath, totems left by the Oracles of the Raven enable the arakkoa to hear the Word of the Raven. Unfortunately, the language of the arakkoa is indecipherable to us.\n\nUsing the Harbinger's pendant, we can understand it. You will be able to take the souls of the arakkoa to understand their language. While you are suffused with the arakkoa's spirit, you can visit the totems and understand their message.\n\nDiscover this for us, {name}.", sourceObjective = "Kill Grishna arakkoa to gain Understanding Ravenspeech for 2 minutes. While under the effects of the spell, you can find and receive the prophecy from the four shrines.", completion = "This is truly disturbing. The arakkoa were peaceful for a long time. This cult of the Raven was nothing more than a gathering of misfits and madmen.\n\nBut their power has grown, that we cannot discount. Perhaps there is more to this Raven than we know.", sourceObjectiveStatus = "unverified-source-field" }
quests[10608] = { id = 10608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Clear", description = "The damned rock flayers are keeping me from my research down in the Singing Ridge!  By digging at the crystals there, with every scratch they are ruining my chances of studying the harmonics of the singing crystals.\n\nYou look like someone who can help me deal with this problem.  Head south and clear those crystal flayers out.", sourceObjective = "Slay 10 Crystal Flayers.", progress = "Have you cleared those crystal flayers out of the Singing Ridge yet?  We can't get started on my research until you do.", completion = "Good riddance to them; that's what I say.  Filthy creatures!\n\nSo, if you're certain that you eliminated those pests, then I have a little research project for you.  I think you'll like it.", sourceObjectiveStatus = "unverified-source-field" }
quests[10609] = { id = 10609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Came First, the Drake or the Egg?", description = "I'm researching the applications of drake essences to my work as a physician.  I think they could be a panacea for a host of maladies!\n\nI need someone to go south to the Singing Ridge and get me some.\n\nWilling to take my temporal phase modulator and use it on the nether whelps that hatch from the nether drake eggs?  Retrieve the essences from whatever they turn into.\n\nWhich, I might add, I'm not certain of what that will be as we're using some pretty dicey, time  and space modifying tech here.", sourceObjective = "Collect 3 Proto-Nether Drake Essences, 3 Adolescent Drake Essences and 3 Mature Drake Essences.", progress = "You have them?  You have the three drake essences that I so dearly need to continue my research?\n\nYou know that those nether drake eggs used to be black dragon eggs?  It's a fact!  But when Draenor blew apart, the resultant nether that raced across what was left mutated the eggs.", completion = "You've no idea how important this research could be.  Thank you!\n\nIt'll be interesting to delve into these essences.  I'm particularly curious to see if the nether effect that changed the black dragon eggs into nether dragon eggs resulted in any potential extra blessings for my studies.\n\nI'm thinking, in fact, that you should be the first person to test out the benefits of my little concoction.  Here, take these preliminary samples and use them when you find the need.", sourceObjectiveStatus = "unverified-source-field" }
quests[10611] = { id = 10611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Art of Fel Reaver Maintenance", description = "The best way to destroy the rest of the Legion's supplies is to use their own weapons against them. I've been working on a rig that will let you take control of one of those Fel Reaver Sentinels below.\n\nThere are a couple things I need to work out, yet. For that, I'll need the manual that Doctor Maleficus keeps locked in a chest near the bottom of the ramp. He probably won't give up the key without a fight, so you'll need to capture it. Bring the fel reaver manual back to me and I'll do the rest.", sourceObjective = "Kill Doctor Maleficus and obtain the Doctor's Key. Use the key to open the Doctor's Strongbox to retrieve The Art of Fel Reaver Maintenance and deliver the book to Nakansi at Invasion Point Cataclysm.", progress = "Did you get that manual?", completion = "This has the information I'm looking for. Just a couple more tweaks, and we'll have you taking control of a fel reaver in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[10612] = { id = 10612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fel and the Furious", description = "<Plexi leafs through the manual.>\n\nWell, this has everything we need, but there's just one problem. Fel Reavers aren't really built to respond to remote control.\n\nWe can modify one for you to use for a short time, but you'll have to work fast, or there's no telling what might happen! I wouldn't be surprised if your little stunt with the fel reaver catches the attention of the Legion's lackeys, either. Keep an eye out, and whatever you do, don't forget to destroy as much as you can!", sourceObjective = "Use a Fel Reaver Control Console to take control of a Fel Reaver Sentinel. Destroy 60 Deathforged Infernals before your fel reaver fails. When your mission is complete, report to Plexi at Invasion Point: Cataclysm.", progress = "You're back, so I'll assume the operation went well. What've you got to report?", completion = "Amazing! You've managed to do what all the gryphonriders in Wildhammer Stronghold couldn't! You've broken the back of the Burning Legion's advance and spared us from annihilation at the hands of their infernals. You have our deepest gratitude for your service, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10613] = { id = 10613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fel and the Furious", description = "<Nakansi leafs through the manual.>\n\nAll the information is here, but be warned. These things weren't built to be controlled remotely.\n\nWe can modify one for you to use for a short time, but you'll have to work fast, or there's no telling what might happen! I wouldn't be surprised if your little stunt with the fel reaver catches the attention of the Legion scum, either. Try to keep yourself safe, but remember, the mission and the safety of Shadowmoon Village come first!", sourceObjective = "Use a Fel Reaver Control Console to take control of a Fel Reaver Sentinel. Destroy 60 Deathforged Infernals before your fel reaver fails. When your mission is complete, report to Nakansi at Invasion Point: Cataclysm.", progress = "You're back, so I'll assume the operation went well. What've you got to report?", completion = "I'll admit it, {name}. I'm impressed by all you've managed to accomplish. Destroying the Legion's ability to make war in Shadowmoon will give us the opportunity to turn the tide elsewhere.", sourceObjectiveStatus = "unverified-source-field" }
quests[10614] = { id = 10614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers on the Wind", description = "I have chased rumors of the Mok'Nathal across Outland with nothing to show for it. Finally, we may have found their home.\n\nBut now that the moment is here, I am filled with unease. Unease that has kept me awake deep into the nights during my search. Will they accept me?\n\nI... know their leader's name: Leoroxx. Seek him out. You must be my eyes in this.", sourceObjective = "Speak with Leoroxx at the Mok'Nathal Village in the Blade's Edge Mountains.", completion = "What brings you to our village?", sourceObjectiveStatus = "unverified-source-field" }
quests[10615] = { id = 10615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruuan Weald", description = "The information you have helped me reveal about the nature of the arakkoa here will be of great interest to another.\n\nWe were visited by members of the Cenarion Expedition, who have also become concerned with the arakkoa's intentions here in the Blade's Edge Mountains.\n\nYou should seek him out. His name is Timeon, and you will find him at Evergrove in Ruuan Weald. Follow the road west from here, then north when it forks in Razor Ridge. Finally, follow the road west when it splits in the Bladed Gulch.", sourceObjective = "Speak with Timeon at Evergrove, which is in the Ruuan Weald in the Blade's Edge Mountains.", completion = "Ah, yes, Dertrok. We spoke briefly about the arakkoa. I must say that our... interests in them vary quite significantly.", sourceObjectiveStatus = "unverified-source-field" }
quests[10617] = { id = 10617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silkwing Cocoons", description = "The silk from the cocoons of the silkwings are used for all manner of things in the village. We can never get enough, and we never have enough.\n\nIt is difficult to harvest the cocoons from the larva once they begin the process of metamorphosis.\n\nOur warriors are occupied with the assault on our village. If you could gather these for us, that would be helpful.", sourceObjective = "Collect 8 Silkwing Cocoons from Silkwing Larva.\n\nKill the Larva quickly or they will turn into Silkwings, ruining their cocoons.", progress = "A swift and sure hand is needed for the harvesting. I hope you will be successful.", completion = "Good quality cocoons, these. I can see you've gotten the hang of harvesting them.\n\nWe have experimented with trying to raise our own silkwing larva, but unfortunately the small ones do not produce enough silk to be of use to us.", sourceObjectiveStatus = "unverified-source-field" }
quests[10618] = { id = 10618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Softest Wings", description = "Hunting silkwing larva is a difficult challenge for our young warriors, but luckily, even if they fail to harvest the cocoon from the larva, we can still use the wings of hatched silkwings.\n\nIn fact, we use the wings for much more than the cocoons, and we can never have too many.\n\nIf you'll be out there, it would be a great help if you could bring me some.", sourceObjective = "Collect 12 Iridescent Wings.", progress = "The wings are quite delicate, but can be inlaid as a decorative element in many of our designs.", completion = "Thank you, {name}. We will use these sooner than you might think.", sourceObjectiveStatus = "unverified-source-field" }
quests[10619] = { id = 10619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ashtongue Tribe", description = "The Ashtongue tribe is feared among all Broken.  It consists of the most vicious and bloodthirsty individuals, handpicked by Akama himself.  They are as fierce and ruthless as any naga, demon or blood elf in Illidan's army and they have been deployed in large numbers at the Ruins of Baa'ri, southwest of here.  Go there and put a dent in their numbers before they get a chance to mount an attack on us.", sourceObjective = "Vindicator Aluumen wants you to go to the Ruins of Baa'ri and slay 3 Ashtongue Handlers, 4 Ashtongue Warriors and 6 Ashtongue Shaman.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", completion = "Glory to the naaru, {name}.  You've done the Light's bidding by defeating those who follow Illidan.", sourceObjectiveStatus = "unverified-source-field" }
quests[10620] = { id = 10620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ridgespine Menace", description = "We hired on to help Toshley when he decided to move to Outland, and we've been on the move ever since.\n\nNow it looks like we've finally put down some roots.  All of the crazy scientists have their projects going, and us Roughriders are here to protect them.\n\nWhat we need right now is for you to go north into Razor Ridge, or east to the Scalewing Shelf, and keep them clear by killing the stalkers.  They're stealthy spiders that live amongst the rock outcroppings, and jump unsuspecting passersby.", sourceObjective = "Slay 10 Ridgespine Stalkers.", completion = "Pretty good for a rookie.  As it turns out, we've got a small group of eggheads that want to go 'observe' the ethereals and their technology up north.  They'll be thrilled to know that you cleared the way for them.\n\nHere, take some of these.  We don't have many, but maybe they'll help you out in the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[10621] = { id = 10621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illidari-Bane Shard", description = "The shard appears to be a piece of a larger weapon. Sharp-looking runes etched into the metal glow with a menacing light.\n\nThe weapon's intended purpose isn't clear to you, but it's hard to ignore. Most of the mo'arg at Legion Hold seem to be working with fragments of the same metal you hold in your hand. Perhaps one of the weaponsmiths at Wildhammer Stronghold might be able to tell you more about it.", sourceObjective = "Bring the Illidari-Bane Shard to Ordinn Thunderfist at Wildhammer Stronghold.", progress = "What have you got there?", completion = "<Ordinn accepts the weapon fragment from you.>\n\nI haven't seen something like this in a long time. Sure, it's made from a rare ore, but this is destined for no mundane weapon, {name}. It's infused with a magic intended to destroy demons. If you obtained this from the Legion, it must be some kind of 'secret weapon' they're planning to deploy against Illidan. What a find!", sourceObjectiveStatus = "unverified-source-field" }
quests[10622] = { id = 10622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Allegiance", description = "Akama has been tracking your progress quite closely, {name}.\n\nThe Ashtongue you've slain at the Ruins of Baa'ri are amongst the most evil Broken known among us... carefully hand-picked by Akama himself to maintain the facade we need to present to Illidan.  The Deathsworn, however, know of Akama's true intentions.\n\nFirst things first.  We need to know that you are not with Illidan.  A Satyr known as Zandras watches over us from above the prison walls on his behalf.  Slay him as proof of your allegiance.", sourceObjective = "Slay Zandras at the Warden's Cage in Shadowmoon Valley and return to Sanoru.", progress = "Have you done what I asked of you, {name}?  Trust is not easily found around these parts.", completion = "Very well, {name}.  Your allegiance is no longer in question.  You may see Akama now.", sourceObjectiveStatus = "unverified-source-field" }
quests[10623] = { id = 10623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illidari-Bane Shard", description = "The shard appears to be a piece of a larger weapon. Sharp-looking runes etched into the metal glow with a menacing light.\n\nThe weapon's intended purpose isn't clear to you, but it's hard to ignore. Most of the mo'arg at Legion Hold seem to be working with fragments of the same metal you hold in your hand. Perhaps one of the weaponsmiths at Shadowmoon Village might be able to tell you more about it.", sourceObjective = "Bring the Illidari-Bane Shard to Grokom Deatheye at Shadowmoon Village.", progress = "What have you got there?", completion = "<Grokom accepts the weapon fragment from you.>\n\nI haven't seen this in years. Not only is it made from a rare ore, but it's not about to be used in an ordinary weapon, {name}.\n\nThese runes imbue the blade with the power to obliterate demons. This shows how much the Legion hates Illidan, if they're willing to arm their own troops with demon-destroying weapons. We could use this to our advantage.", sourceObjectiveStatus = "unverified-source-field" }
quests[10624] = { id = 10624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Haunted History", description = "Have you felt the cold chill? Perhaps what you thought was a hand on your shoulder? That was not your mind playing tricks on you, {race}. The land is haunted. Ghosts litter the landscape, stuck here for all eternity.\n\nWould you like to see them? Are you sure about that? These types of things tend to change a person - and not for the better.\n\nVery well, I will need you to collect for me the ever-burning ash that is found near any of the fel lava pools of western Shadowmoon. Anywhere near green lava...", sourceObjective = "Chief Apothecary Hildagard at Shadowmoon Village in Shadowmoon Valley wants you to bring her 15 Ever-burning Ash samples.", progress = "What do you mean? I'm going to make something out of the ash - obviously.", completion = "Your world is about to change, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10625] = { id = 10625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spectrecles", description = "I call them \"Spectrecles.\" Clever, no? When you equip these goggles, you will be able to see the spirits of Shadowmoon Valley.\n\nBefore I let you have them, though, you must promise me that you will help us clear out the ghosts at the village.\n\nTake the goggles and destroy any and all spirits that you see wandering about Shadowmoon Village. Hopefully, destroying these spirits will force any that remain to move elsewhere.", sourceObjective = "Chief Apothecary Hildagard at Shadowmoon Village in Shadowmoon Valley wants you to slay 12 Shadowmoon Zealots.", progress = "If you lose your goggles, let me know and I will craft another pair.", completion = "Gorefiend? T... Teron Gorefiend? But... How?\n\nHow could Gorefiend be here? This is impossible!\n\nThe legend of Teron Gorefiend is one that causes even the Forsaken to tremble in fear. By all accounts, Gorefiend was a warlock of Gul'dan - extremely powerful in his own right. When Gorefiend was slain by Orgrim Doomhammer, Gul'dan took the soul of the fallen warlock and placed it inside the broken shell of a slain knight of Stormwind. And so was born the first death knight of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[10626] = { id = 10626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capture the Weapons", description = "With a larger supply of this material, we might be able to forge a weapon for you to use.\n\nThe two pit lords at Legion Hold, Makazradon and Morgroron, have already been equipped with these anti-demon weapons. We have no way of knowing how many more the Legion intends to produce, but if we can capture these prototypes, there should be enough for our project.\n\n<Ordinn grins.>\n\nThere's a certain amount of satisfaction in using the Legion's own 'secret weapons' against them, don't you think?", sourceObjective = "Ordinn Thunderfist at Wildhammer Stronghold wants you to bring him Mazakradon's Glaive and Morgroron's Glaive.", progress = "Did you capture those prototypes?", completion = "These should work nicely. Now, let's forge them into a more useful form.", sourceObjectiveStatus = "unverified-source-field" }
quests[10627] = { id = 10627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capture the Weapons", description = "With a larger supply of this material, I can forge a weapon suitable for you.\n\nThe two pit lords at Legion Hold, Makazradon and Morgroron, have already been equipped with these anti-demon weapons. Capturing those two weapons should provide us with enough material to make your weapon, and then some.\n\nI can't wait to bring the battle to the enemy using these weapons. That'll teach the Legion to trifle with anti-demon magics.", sourceObjective = "Grokom Deatheye at Shadowmoon Village wants you to bring him Mazakradon's Glaive and Morgroron's Glaive.", progress = "Did you capture those prototypes?", completion = "These should work nicely. Now, let's forge them into a more useful form.", sourceObjectiveStatus = "unverified-source-field" }
quests[10628] = { id = 10628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akama", description = "You've proven what side you're on.  I will reveal to you our leader's hideout.\n\nFollow the halls beyond; there will be an underground passage hidden by stagnant water on your right.\n\nI must warn you, {name}.  You are not to speak to anyone of what you see there.", sourceObjective = "Speak to Akama inside the hidden chamber in the Warden's Cage.", completion = "Hail, {name}.  There is much we need to talk about.\n\nI hope your mind is an open one.  The decisions I make are not understood by many.  Only my closest collaborators have understanding of the portents I see and the signs I await.\n\nWhen I joined forces with Illidan it was based on visions foretelling that otherwise my race would have been destroyed.  I've waited patiently for other signs and visions to come to pass... Velen's exodus... the opening of the Dark Portal... and now... your arrival.", sourceObjectiveStatus = "unverified-source-field" }
quests[10629] = { id = 10629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shizz Work", description = "I finally got my shredder working but I seem to have lost the keys.  I keep a pack of felhounds to protect my camp.  They don't do a very good job and they like to bite me a lot.  They also like shiny things.  I think this one felhound I have may have eaten my shredder keys.  I'll pay you if you'll take my felhound on a walk.  Kill some helboars and let him eat.  He'll do his business.  When he's done, see if you can't find the keys in his \"leavings.\"", sourceObjective = "Use the Felhound Whistle to summon a Fel Guard Hound. Take the Fel Guard Hound for a walk and kill some Deranged Helboars. Search for the Shredder Keys in the Fel Guard Hound's \"leavings.\"  Return the Shredder Keys to Foreman Razelcraz by the mine northwest of Thrallmar.", progress = "Did you manage to find my keys?  I'm sure one of my felhounds ate them.  It's probably the one I sent with you.  Probably.", completion = "You smell terrible.  But you found my keys!  Thank you so much.  Now I can get my shredder started and make some money.  Pretty soon I will have enough money to leave Outland.  I don't know why you stay; I hate this place.  Wouldn't you rather be back in Booty Bay?  \n\nMaybe do some fishing?", sourceObjectiveStatus = "unverified-source-field" }
quests[10630] = { id = 10630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beneath Thrallmar", description = "I'm almost back in business.  Problem is all these gan'arg are in my mine.  I can't send my peons in and even once I fix this shredder I wouldn't want to risk it in combat. Deep down in the mine the gan'arg have a leader.  If you kill him maybe the gan'arg will leave.  Then I could make some money and buy my way out of here.", sourceObjective = "Kill Urga'zz and return to Foreman Razelcraz by the mine northwest of Thrallmar.", progress = "Is he dead yet?  I'm too scared to look.", completion = "All those gan'arg are sure to clear out now.  I'll be back in Booty Bay within a week.  I can't wait to go fishing again.  Coming to Outland was a mistake.  If you'll take my advice, you'll head back the way you came.  Spend some time in Stranglethorn, or maybe, if you feel adventurous, head to Un'Goro Crater.  Just don't stay here.", sourceObjectiveStatus = "unverified-source-field" }
quests[10632] = { id = 10632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting Your Teeth", description = "It's nice that you've been helping out Toshley and his scientists.  I, however, do not have the luxury of indulging in my 'personal' interests.\n\nIf you want to make a difference around here, you'll do what I ask of you, and right now, I need weapons.\n\nOur guns are effective at range, but when the bugs get in close, we need to have powerful melee weapons as a backup.\n\nThe teeth of the daggermaw lashtails in the northern part of the Razor Ridge make for great vibro-weapon blades.  Scare me up some.", sourceObjective = "Collect 5 Extra Sharp Daggermaw Teeth.", progress = "How's that collection of teeth coming along?\n\nI'm sure that you're going to do a fine job of getting them for us.  While you're doing that, we'll just hold down the outpost here.", completion = "Good work, kid.  All of the pain is worth it if even one of my soldiers' lives is saved by your efforts.\n\nI think you should benefit from your sweat and tears, too.  Since we're going to have a new batch of weapons soon, why don't you take one of mine?", sourceObjectiveStatus = "unverified-source-field" }
quests[10633] = { id = 10633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teron Gorefiend - Lore and Legend", description = "Stories abound about the life of Teron Gorefiend, but most are just that - stories. We do not know what happened to Gorefiend after he returned to Draenor.\n\nThe only thing we are certain of is that he has already died once.\n\nI have heard the scouts here speaking of an ancient orc spirit that resides at the Altar of Shadows, far to the southeast, across the Netherwing Fields and through Netherwing Pass. Take the Spectrecles and track this orc down. He will surely have more information on Gorefiend.", sourceObjective = "Chief Apothecary Hildagard at Shadowmoon Village in Shadowmoon Valley wants you to find the Ancient Shadowmoon Spirit.\n\nIf you lose your Spectrecles, Chief Apothecary Hildagard can make you a new pair.\n\nProvided item:", completion = "Gorefiend? Why, I have not heard that name in ages!\n\nAfter the Second War, Gorefiend returned here, along with his death knights. Unable to cope with the terrible nature of his new form and without the support of his beloved leader, Gul'dan, Gorefiend killed himself.\n\nIf he walks these lands now as a spirit, it is news to me. Yet, perhaps I can divine such knowledge with your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[10634] = { id = 10634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Divination: Gorefiend's Armor", description = "In life, Gorefiend was a monster, but in death, Gorefiend was an unmitigated terror.\n\nTo the southeast you will find Netherwing Ledge. What was once part of the mainland of Shadowmoon is now a floating island in the sky.\n\nVhel'kur, spawn of Deathwing, once called it his home, but now knows it as his grave. He flies an endless circle above the island, seething at his defeat to Gorefiend.\n\nIf you are to recover the Gorefiend's armor, it is Vhel'kur that you must defeat.", sourceObjective = "The Ancient Shadowmoon Spirit at the Altar of Shadows in southeast Shadowmoon Valley wants you to recover Gorefiend's Armor.", progress = "Fly to Netherwing Ledge to recover the piece.", completion = "I must have all of the pieces before I am able to divine the fate of Gorefiend.", sourceObjectiveStatus = "unverified-source-field" }
quests[10635] = { id = 10635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Divination: Gorefiend's Cloak", description = "Many a cruel act he committed but none so cold as the slaughter of the clerics of Karabor.\n\nAfter Gul'dan's Horde defeated the draenei of Karabor, the surviving clerics of Karabor were marched out, told that they were to be taken to Hellfire Citadel as prisoners of war.\n\nGorefiend, not yet a death knight, murdered each and every last one of them in cold blood. They now roam in front of the Black Temple with vengeance in their hearts.\n\nIt is the clerics of Karabor that hold the cloak of Gorefiend.", sourceObjective = "The Ancient Shadowmoon Spirit at the Altar of Shadows in southeast Shadowmoon Valley wants you to recover Gorefiend's Cloak.", progress = "You must use the Spectrecles if you wish to see the spirits of Shadowmoon.", completion = "When I have all three of the pieces in my possession, I will be able to divine the whereabouts of Gorefiend.", sourceObjectiveStatus = "unverified-source-field" }
quests[10636] = { id = 10636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Divination: Gorefiend's Truncheon", description = "One by one they knelt before him, offering their lives as a show of allegiance. Gorefiend hoisted his sickle and cut clean their heads. Shortly after this slaughter, Gorefiend took his own life.\n\nBut this was no act of contrition! No, Gorefiend sought immortality! From the corpses of the fallen death knights rose the Ghostriders of Karabor.\n\nThey now ride the roads encircling the Hand of Guldan, awaiting the day that their master returns. It is they who hold the truncheon of Gorefiend. Retrieve it...", sourceObjective = "The Ancient Shadowmoon Spirit at the Altar of Shadows in southeast Shadowmoon Valley wants you to recover Gorefiend's Truncheon.", progress = "You must use the Spectrecles if you wish to see the spirits of Shadowmoon.", completion = "Only with all three united may I divine the secrets you so desperately seek!", sourceObjectiveStatus = "unverified-source-field" }
quests[10637] = { id = 10637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Necessary Distraction", description = "The weapons are authentic, as we feared.  Illidan is training demon hunters at the Ruins of Karabor and we must put an end to it.\n\nDo not be fooled by their name, {name}, their power will be used against us as often as against any demon.\n\nTheir warlocks summon and subdue demons to be used as part of the initiates' training.  A pit lord named Azaloth has proven too strong to be used in training and is kept banished.  Find a way to let him loose on his captors.  That should buy us the time we need.", sourceObjective = "Exarch Onaala wants you to return to the Ruins of Karabor and find a way to unleash Azaloth on his captors.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Have you completed the task I asked of you?", completion = "Let us hope that distraction bought us the time we need to fully learn what we need of the training grounds at Karabor.", sourceObjectiveStatus = "unverified-source-field" }
quests[10638] = { id = 10638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "NOT A QUEST", description = "Seek your trainer in Silvermoon City.", sourceObjective = "Seek <NAME> in the <DISTRICT> of Silvermoon City.", sourceObjectiveStatus = "unverified-source-field" }
quests[10639] = { id = 10639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teron Gorefiend, I am...", description = "With Gorefiend's items restored, there is but one last piece to this puzzle: A host.\n\n<The ancient shadowmoon spirit's lips curl up  to form a wicked grin.>\n\nSurely you did not believe the fairy tale that I told you. The Altar of Shadows is my prison. Without your help, I would have been stuck here for all eternity. Now, I will take over your body and you will destroy my captors and break these bonds. Refuse and we will both be stuck here forever.\n\nTeron Gorefiend will be free!", sourceObjective = "The Ancient Shadowmoon Spirit has used you as a pawn! Now that you have collected the items he required, he has revealed himself to be Teron Gorefiend. To break free of his possession, you must do his bidding and slay Karsius the Ancient Watcher.\n\nIf you succeed, return to Chief Apothecary Hildagard at Shadowmoon Village.", completion = "You did what? FOOL!\n\nYou must right this wrong. After all, it is your fault. Take one of these helmets. They are each infused with the ever-burning ash that you retrieved for me. More importantly, they will allow you to see the ghosts of Shadowmoon, including Teron Gorefiend.\n\nShould you ever find Teron Gorefiend, destroy him.", sourceObjectiveStatus = "unverified-source-field" }
quests[10640] = { id = 10640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Altruis", description = "It is rare in this day and age to hear of those who follow the path of the demon hunter.  It is rarer still to find someone who does and has no allegiance to Illidan.\n\nThere are rumors of one such individual here in Outland.  One name is said to be feared in the Legion fields of Nagrand more than any army of Aldor vindicators.  That name is Altruis.\n\nGo to western Nagrand and find him.  He might be willing to shed some light on these new demon hunter training grounds.", sourceObjective = "Travel to western Nagrand and find Altruis the Sufferer.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", completion = "You've come a long way, stranger.  I'm surprised whoever sent you has heard of me.", sourceObjectiveStatus = "unverified-source-field" }
quests[10641] = { id = 10641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against the Legion", description = "The Burning Legion has proven its capacity to corrupt mortal souls time and again.  If I'm to entrust you with the knowledge you seek, I must have proof of your allegiance.\n\nA demoness known as Sathal has eluded me for a long time as she's gifted with an incorporeal form.\n\nShe watches over the wrath priestesses as they do her bidding at Forge Base: Gehenna.  Slay one of her minions and spill her blood on the ground.  This affront should cause Sathal to materialize temporarily.  Slay her while you can.", sourceObjective = "Altruis the Sufferer wants you to obtain Freshly Drawn Blood from a Wrath Priestess at Forge Base: Gehenna in Netherstorm. Spill it on the ground and slay the Avatar of Sathal. Return to Altruis when you've completed this task.", progress = "Have you slain the demoness?", completion = "You've proven you're not tainted by the Legion's touch and the enemy of my enemy is my friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[10642] = { id = 10642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ghost in the Machine", description = "I fear that these dwarves do not understand what they have built upon. This area was once the ancestral grounds for the Shadowmoon orcs. I speak of spirits, {race}.\n\nFor nearly twenty years they have laid dormant beneath the Wildhammer Stronghold, but recently, something has riled them up.\n\nVenture beyond the gates of Wildhammer and seek out the pools and rivers of fel lava found across this land. Near the lava will be ever-burning ash. Bring me this ash so that I may craft something that will help us.", sourceObjective = "Zorus the Judicator at Wildhammer Stronghold in Shadowmoon Valley wants you to bring him 15 Ever-burning Ash samples.", progress = "Aye, a duality exists... I can feel it.", completion = "<Zorus begins to craft something out of the ash samples.>\n\nIt is done. Behold, Spectrecles!", sourceObjectiveStatus = "unverified-source-field" }
quests[10643] = { id = 10643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harbingers of Shadowmoon", description = "Let it be known that Zorus does have a sense of humor.\n\nEnough small talk. Don the Spectrecles so that you are able to see the Shadowmoon orc spirits that wander this stronghold. Do not be frightened as we are truly the invaders here. Alas, they must be destroyed, for their time has long since passed.\n\nDestroy the Shadowmoon harbingers infesting Wildhammer Stronghold and return to me.", sourceObjective = "Zorus the Judicator at Wildhammer Stronghold in Shadowmoon Valley wants you to slay 12 Shadowmoon Harbingers.", progress = "If you lose your goggles, let me know and I will craft another pair.", completion = "You claim to have heard the ghosts whisper to you? And they mentioned Teron Gorefiend?\n\n<Zorus shudders.>\n\nYes... I know Teron Gorefiend. Rather, I knew of him. He has long been thought dead. What could these ghosts be speaking of?", sourceObjectiveStatus = "unverified-source-field" }
quests[10644] = { id = 10644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teron Gorefiend - Lore and Legend", description = "Stories abound about the life of Teron Gorefiend, but most are just that - stories. We do not know what happened to Gorefiend after he returned to Draenor.\n\nThe only thing we are certain of is that he has already died once.\n\nI have heard the scouts here speaking of an ancient orc spirit that resides at the Altar of Shadows, far to the east, across the Netherwing Fields and through Netherwing Pass. Take the Spectrecles and track this orc down. He will surely have more information on Gorefiend.", sourceObjective = "Zorus the Judicator at Wildhammer Stronghold in Shadowmoon Valley wants you to find the Ancient Shadowmoon Spirit.\n\nIf you lose your Spectrecles, Zorus the Judicator can make you a new pair.\n\nProvided item:", completion = "Gorefiend? Why, I have not heard that name in ages!\n\nAfter the Second War, Gorefiend returned here, along with his death knights. Unable to cope with the terrible nature of his new form and without the support of his beloved leader, Gul'dan, Gorefiend killed himself.\n\nIf he walks these lands now as a spirit, it is news to me. Yet, perhaps I can divine such knowledge with your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[10645] = { id = 10645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teron Gorefiend, I am...", description = "With Gorefiend's items restored, there is but one last piece to this puzzle: A host.\n\n<The ancient shadowmoon spirit's lips curl up  to form a wicked grin.>\n\nSurely you did not believe the fairy tale that I told you. The Altar of Shadows is my prison. Without your help, I would have been stuck here for all eternity. Now, I will take over your body and you will destroy my captors and break these bonds. Refuse and we will both be stuck here forever.\n\nTeron Gorefiend will be free!", sourceObjective = "The Ancient Shadowmoon Spirit has used you as a pawn! Now that you have collected the items he required, he has revealed himself to be Teron Gorefiend. To break free of his possession, you must do his bidding and slay Karsius the Ancient Watcher.\n\nIf you succeed, return to Zorus the Judicator at Wildhammer Stronghold.", completion = "You did what? FOOL!\n\nYou must right this wrong. After all, it is your fault. Take one of these helmets. They are each infused with the ever-burning ash that you retrieved for me. More importantly, they will allow you to see the ghosts of Shadowmoon, including Teron Gorefiend.\n\nShould you ever find Teron Gorefiend, destroy him.", sourceObjectiveStatus = "unverified-source-field" }
quests[10646] = { id = 10646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illidan's Pupil", description = "You've proven your allegiance, {name}.  You must forgive my caution, but in this world things are not what they appear.\n\nI will tell you about Varedis when you're ready.", sourceObjective = "Listen to Altruis's story.", progress = "Varedis is powerful, yes.  There is a way he can be defeated, however.", completion = "You know the story now.  Only one thing remains to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[10647] = { id = 10647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Uvuros, Scourge of Shadowmoon", description = "Wanted - DEAD:\n\nUvuros, scourge of Shadowmoon Valley.\n\nBy order of Overlord Or'barokh, the fel beast, Uvuros, is to be killed on sight and his mane stripped from his carcass as proof of deed. Return the fiery mane of the beast to Warcaller Sardon Truslice should you succeed.\n\nUvuros was last seen at the Hand of Gul'dan, located in the heart of Shadowmoon Valley - east of Shadowmoon Village.", sourceObjective = "Slay Uvuros and recover Uvuros's Fiery Mane. Return it to Warcaller Sardon Truslice at Shadowmoon Village in Shadowmoon Valley.", progress = "Here ta collect a reward, mon?", completion = "Quite da haul you got der, mon. Well done! An' ya be getting' yer reward. Don't ya worry!", sourceObjectiveStatus = "unverified-source-field" }
quests[10648] = { id = 10648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Uvuros, Scourge of Shadowmoon", description = "Wanted - DEAD:\n\nUvuros, scourge of Shadowmoon Valley.\n\nBy order of Thane Yoregar, the fel beast, Uvuros, is to be killed on sight and his mane stripped from his carcass as proof of deed. Return the fiery mane of the beast to Warcaller Beersnout should you succeed.\n\nUvuros was last seen at the Hand of Gul'dan, located in the heart of Shadowmoon Valley - northeast of Wildhammer Stronghold.", sourceObjective = "Slay Uvuros and recover Uvuros's Fiery Mane. Return it to Warcaller Beersnout at Wildhammer Stronghold in Shadowmoon Valley.", progress = "I hope you've done somethin' special, lad. Otherwise, buzz off!", completion = "Yep, here's your reward. Don't go spendin' it all in once place.", sourceObjectiveStatus = "unverified-source-field" }
quests[10649] = { id = 10649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Book of Fel Names", description = "I sympathize with your intentions of stopping Varedis and his followers, but you won't stand a chance against him.  That is, unless you find the artifact that gave him his power.\n\nThe Book of Fel Names is rumored to be in the possession of Blackheart the Inciter inside the Shadow Labyrinth in Auchindoun.  Obtaining it will be your only hope against Varedis.", sourceObjective = "Venture inside the Shadow Labyrinth in Auchindoun and obtain the Book of Fel Names from Blackheart the Inciter. Return to Altruis in Nagrand once you've completed this task.", progress = "Have you obtained the book, {name}?", completion = "I was able to sense the book's power from yards away.  The temptation to keep it is... very strong.", sourceObjectiveStatus = "unverified-source-field" }
quests[10650] = { id = 10650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Aldor", description = "This book... I could use it to increase my power tenfold...  No!  It would end up corrupting my very soul, this I am sure of.  Return to those who sent you here, {name}.\n\nYou now have the means to stop Varedis.  Wait until he manifests his demonic form through metamorphosis, at that point you will need to burn the book in his presence.  That will be the only way you can deprive him of his power.", sourceObjective = "Speak with Exarch Onaala at the Altar of Sha'tar in Shadowmoon Valley.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", completion = "You bring this abomination of a book to this holy site?  You'd better have a very good explanation, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[10651] = { id = 10651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varedis Must Be Stopped", description = "We must dispose of this foul artifact, but not before we use it to dispose of Varedis's powers.\n\nWe need to permanently shut down the Ruins of Karabor training grounds, which will mean killing not only Varedis but also the three night elf masters that assist him: Alandien, Theras and Netharel.\n\nGather a suitable force and return to the Ruins of Karabor.  Follow Altruis's instructions for defeating Varedis.  For all of our sakes, I hope they work.", sourceObjective = "Exarch Onaala wants you to go to the ruins of Karabor and slay Alandien, Theras, Netharel and Varedis. Use the Book of Fel Names when Varedis uses Metamorphosis to weaken him. Return to Exarch Onaala with the Book of Fel Names after you've completed this task.\n\nCompleting quests for the Aldor will cause your Scryers reputation to decrease.", progress = "Have you completed what I asked of you, {name}?", completion = "Excellent work, {name}!  Your victory over Varedis will have a tremendous impact on our war against Illidan.\n\nYou've proven yourself not just to the Aldor but to all of Outland.  Allow me to destroy what remains of that horrible book.", sourceObjectiveStatus = "unverified-source-field" }
quests[10652] = { id = 10652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Enemy Lines", description = "All arrangements have been made to take you to where our spies are hiding.  Just come see me when you're ready and we'll get you on your way.", sourceObjective = "Speak to Veronia when you're ready to depart to Manaforge Coruu. Once there, speak to Caledis Brightdawn.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", completion = "Welcome, {class}.  Try not to give our position away.\n\nWe wouldn't last long if Kael's cronies sniff us out.", sourceObjectiveStatus = "unverified-source-field" }
quests[10653] = { id = 10653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marks of Sargeras", description = "By now it should be clear to you why we oppose the Burning Legion and those who serve them.\n\nIf you wish to prove yourself to the Aldor, bring me the insignias of high-ranking Legion and their Shadow Council followers.  The highest-ranking Legion can be found in Netherstorm and Shadowmoon Valley.", sourceObjective = "Bring 10 Marks of Sargeras to Adyen the Lightwarden in Shattrath City.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Do you bear any of our enemies' insignias, {name}?", completion = "Facing the demons of the Burning Legion and the mad cultists that worship them is no small feat, {name}.  You've shown great dedication and courage.  Keep it up and your renown among the Aldor will continue to grow.", sourceObjectiveStatus = "unverified-source-field" }
quests[10654] = { id = 10654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Marks of Sargeras", progress = "Do you bear more of our enemies' insignias, {class}?  The Burning Legion continues to be a threat and we continue to pursue them anywhere that we find them.", completion = "You continue to prove your worth, {name}.  Fight the enemies of the Light wherever you may find them; your actions will be well-rewarded." }
quests[10655] = { id = 10655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Single Mark of Sargeras", progress = "I'll take any leftover marks you might have.  Do not worry; your actions will be duly noted.", completion = "You continue to prove your worth, {name}.  Fight the enemies of the Light wherever you may find them; your actions will be well-rewarded." }
quests[10656] = { id = 10656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunfury Signets", description = "As you might know, the Scryers and the armies of Kael'thas are at war.  Kael sees us as a threat to his influence over other blood elves and has tried to crush us time and again.\n\nIf you wish to aid us in our battle against Kael'thas, there are plenty of targets for you to go after.  Kael's highest ranking soldiers wear Sunfury signets to mark their ranks.  You will find them all over Netherstorm and Shadowmoon Valley.", sourceObjective = "Magistrix Fyalenn in Shattrath City wants you to bring her 10 Sunfury Signets.\n\nPerforming quests for the Scryers will cause you Aldor reputation level to decrease.", progress = "Go on, {name}.  Speak.", completion = "Kael's Sunfury army is extremely well-trained.  Very impressive job, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10657] = { id = 10657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ride the Lightning", description = "We haven't kept the use of the Zephyrium Capacitorium under budget.  But, it occurs to me that the serpents of the Scalewing Shelf to the east have a lightning breath and glands that we can make use of.\n\nI've repolarized the magneto collector to absorb lightning strikes and I want you to head up there, activate it on yourself, and get us some cheap fuel from those serpents.", sourceObjective = "Use the Repolarized Magneto Sphere to absorb 25 lightning strikes from the Scalewing Serpents. Also, collect 5 Scalewing Lightning Glands.", progress = "The trick to using the repolarized magneto sphere is to know when to turn it off before you end up getting truly fried.\n\nOf course, you need to balance that against how many of those flying serpents you want to have to face.\n\nSpeaking of which, have you managed to charge up the sphere?", completion = "Woo hoo, it worked!  To be honest I wasn't sure... I calculated a twenty-three point seven two chance that you'd implode by the third strike.\n\n<Toshley grins innocently.>\n\nSo, now we know that the sphere works, we should have no problem meeting our energy needs for the Zephyrium Capacitorium.  Well, that is if we can find more volunteers to go out there and get zapped.\n\nStill, you've pioneered our efforts and deserve something in return!", sourceObjectiveStatus = "unverified-source-field" }
quests[10658] = { id = 10658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Sunfury Signets", progress = "What have you done for us lately, {name}?  The war against Kael'thas is not going to fight itself, you know?", completion = "Excellent!  That'll show Kael'thas not to underestimate our power." }
quests[10659] = { id = 10659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Single Sunfury Signet", progress = "Even the smallest contribution to our cause is noted, {name}.  Our enemies are many, but we shall prevail!", completion = "Kael's army will soon fall." }
quests[10660] = { id = 10660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Strange Creatures...", description = "I am interested in learning more about the strange reptiles that mill about the lava flows of Shadowmoon Valley. Never have I seen beasts able to withstand the searing heat of molten lava!\n\nOutside of Shadowmoon Village, where the ground has ruptured and lava flows through the cracks, you will find felfire diemetradons. Slay them and bring me their spleens. From their spleens I will be able to begin preliminary analysis of their resistance to heat.\n\nBegin your search to the southeast.", sourceObjective = "Researcher Tiorus at Shadowmoon Village in Shadowmoon Valley wants you to recover 8 Felfire Spleens.", progress = "Spleens! I need spleens!", completion = "<Researcher Tiorus takes the spleens and starts his examination.>\n\nThis may take a while. Take these coins for your hard work.", sourceObjectiveStatus = "unverified-source-field" }
quests[10661] = { id = 10661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spleendid!", description = "Have you ever heard of food that cooks itself and stays hot forever? Dare to dream, I say!\n\nBut maybe it's not a dream at all! Outside the fortress, near the lava pools and streams, you can find beasts that thrive in the sizzling heat. They're called felfire diemetradons.\n\nThe dwarves around here tell me that those diemetradons have the tastiest spleens ever and that the spleens practically come pre-cooked! Bring me those spleens and I'll give you some coin.\n\nStart your search directly east of here.", sourceObjective = "Gnomus at Wildhammer Stronghold in Shadowmoon Valley wants you to recover 8 Felfire Spleens.", progress = "Spleens! I need spleens!", completion = "<Gnomus hungrily grabs at the spleens.>\n\nHere's your coin as promised. I'll call for you if I need more spleens.\n\nSo delicious... I dare say that they are 'spleendid!'", sourceObjectiveStatus = "unverified-source-field" }
quests[10662] = { id = 10662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hermit Smith", description = "<Ordinn examines the results from his attempt at smithing the metal and shakes his head.>\n\nThis is beyond my ability, but that's not to say the weapon can't be recreated for your use.\n\nThere was a talented smith who accompanied the Sons of Lothar to Draenor, David Wayne. He was a remarkable blacksmith, but chose to leave the expedition. These days, he lives in a small camp on a peninsula east of Firewing Point in Terokkar Forest. Take the ingots to him and see if he can help you with the weapon.", sourceObjective = "Bring the Box of Ingots to David Wayne at Wayne's Refuge in Terokkar Forest.", progress = "What brings you here, {class}? I don't get many visitors.", completion = "Ordinn sent you with these?\n\n<The smith examines the ingots.>\n\nHe was right. Most of the magic is gone, but I can still sense traces of it. With some work and a few 'exotic' resources, I can forge you a powerful anti-demon sword from this metal.", sourceObjectiveStatus = "unverified-source-field" }
quests[10663] = { id = 10663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hermit Smith", description = "<The orc shakes his head at his failure.>\n\nThis is beyond my ability, but that's not to say the weapon can't be recreated.\n\nIt pains me to suggest this, but your only hope may be a human smith by the name of David Wayne. It's true he was once a member of the Alliance's expedition, but that was a long time ago and he has since left the Sons of Lothar. These days, he lives in a small camp on a peninsula east of Firewing Point in Terokkar Forest. Take the ingots to him and see if he can help you.", sourceObjective = "Bring the Box of Ingots to David Wayne at Wayne's Refuge in Terokkar Forest.", progress = "What brings you here, {class}? I don't get many visitors.", completion = "<The smith frowns and examines the ingots.>\n\nI'll be frank with you, {class}. I'm a relic of an age when cooperation with the Horde was unthinkable.\n\nI am not so blind as to see that we do not have common enemies. I will help you to reforge the anti-demon weapon but it's going to take a lot of hard work and a few 'exotic' resources.", sourceObjectiveStatus = "unverified-source-field" }
quests[10664] = { id = 10664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Additional Materials", description = "The ingots that you brought contain most of the metal I'll need to forge the sword's blade, but I'll need a variety of things to create other parts of the weapon.\n\nLet's see, among the things I don't have here are an adamantite frame, some heavy knothide leather, and a demon warding totem. Skilled crafters should be able to produce the first two, but the third is only sold by the reagent vendor in Shattrath's Lower City, Fantei. You'll find him with the other tradesmen.", sourceObjective = "David Wayne at Wayne's Refuge wants you to bring him an Adamantite Frame, 4 Heavy Knothide Leather, and a Demon Warding Totem.", progress = "Did you get those materials?", completion = "<The smith accepts the materials, nodding approvingly.>\n\nThese will suffice. The remainder of the materials I'll need won't be quite so easy to come by.", sourceObjectiveStatus = "unverified-source-field" }
quests[10665] = { id = 10665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fresh from the Mechanar", description = "Working with the ingots you brought is going to require a lot of heat -- rather more than a conventional forge can supply.\n\nI'm going to need a supplemental heat source for the forge and there are very few things in Outland that can supply that kind of power.\n\nThe Mechanar area of Tempest Keep turns out manacells containing an incredible amount of power. Find one of the overcharged manacells from the stacks around Mechano-Lord Capacitus and bring it back here.", sourceObjective = "David Wayne at Wayne's Retreat wants you to bring him an Overcharged Manacell.", progress = "Were you able to smuggle a manacell out of the Mechanar.", completion = "This is even more potent than I expected! With this much power, I could forge a dozen blades!", sourceObjectiveStatus = "unverified-source-field" }
quests[10666] = { id = 10666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lexicon Demonica", description = "Recreating the enchantments on the blade requires several spells to be spoken in demonic.\n\nIt's not something I was taught during my training as an apprentice, but there's no way around it. There's a book, called the Lexicon Demonica, that will provide most of the words I need, but it's in the hands of a powerful Shadow Council warlock.\n\nDeep in the halls of Auchindoun's Shadow Labyrinth, it is held by Grandmaster Vorpil. Do whatever you must to secure the book and bring it to me.", sourceObjective = "Obtain the Lexicon Demonica from Grandmaster Vorpil and bring it to David Wayne at Wayne's Refuge.", progress = "Have you retrieved the book?", completion = "<David leafs through the book's pages, shuddering.>\n\nThis is not something to be trifled with, {name}. After the weapon is created, I will destroy it. There is enough demonic power about in the world without this text out in the open.", sourceObjectiveStatus = "unverified-source-field" }
quests[10667] = { id = 10667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Underworld Loam", description = "The frame that you brought me earlier will not be sufficient to hold molten metal without reinforcement. A rare kind of earth can be used to cool and imbue the frame, giving the adamantite an unnatural strength.\n\nUnderworld loam, as the earth is known, is accorded great value among the naga. Few enough of them possess it, and in Outland, I know of only one naga who uses it -- Hydromancer Thespia, who resides in the Steamvault of Coilfang Reservoir.", sourceObjective = "Get a Vial of Underworld Loam from Hydromancer Thespia and bring it to David Wayne at Wayne's Refuge.", progress = "Have you secured the underworld loam?", completion = "This should do the trick. I'd hoped for a bit more, but to be honest, we were lucky to get our hands on any at all out here.", sourceObjectiveStatus = "unverified-source-field" }
quests[10668] = { id = 10668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against the Illidari", description = "I still have respect for Illidan.  Without him I would not have found my path.\n\nHe is not who he once was, however.  His soul has been corrupted by power, his mind has been twisted by defeat.  He has become what I am sworn to destroy and his pet servants, the Illidari, are as much of an abomination as any demon of the Burning Legion.\n\nHis grasp on Outland is slipping yet his reach is still vast.  Prove you're not with him by slaying his lieutenant Lothros at Illidari Point in Shadowmoon Valley.", sourceObjective = "Altruis the Sufferer wants you to slay Lothros at Illidari Point in Shadowmoon Valley.", completion = "So you're not with Illidan.  You're one step closer to gaining my full trust.", sourceObjectiveStatus = "unverified-source-field" }
quests[10669] = { id = 10669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against All Odds", description = "Some demons pledge allegiance to no one but themselves.  A true enemy of demons finds and destroys his prey regardless of affiliation, however.\n\nThe demon Xeleth - a Legion defector - was once worshipped as a god by primitive swamp creatures in Zangarmarsh.  When Draenor was nearly destroyed, he retreated into a slumber deep beneath Marshlight Lake.  Find the portal at the lake and plant this spear into the ground.\n\nXeleth will awake - be ready to slay him and prove you're an enemy to all demons.", sourceObjective = "Altruis the Sufferer wants you to take the Imbued Silver Spear and use it at Portal Clearing near Marshlight Lake in Zangarmarsh to awake Xeleth. Return to Altruis after you've slain the demon.", progress = "You've returned.  Has Xeleth been slain?", completion = "Well done, {name}.  He still remembered the day I drove this spear into him?  That was so long ago...", sourceObjectiveStatus = "unverified-source-field" }
quests[10670] = { id = 10670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tear of the Earthmother", description = "The sword's enchantments must be contained within a powerful focus, such as a gem. I know of a gem that we can use for this purpose, for there are few that can play host to such powerful magics without shattering.\n\nThe gem we need is called the tear of the earthmother. It's a powerful artifact in the hands of the ogres who created it, and Warbringer O'mrogg, who currently holds the gem, has many powerful allies in Hellfire Citadel's Shattered Halls. Take care in retrieving the tear, {name}.", sourceObjective = "Recover the Tear of the Earthmother from Warbringer O'mrogg and return it to David Wayne at Wayne's Refuge.", progress = "Were you able to wrest the gem from the grip of O'mrogg?", completion = "<David Wayne holds the gem up, to the light, admiring it.>\n\nIt's aboslutely flawless, and that's exactly what we'll need. A flawed gem would endanger the weapon's wielder, twisting the magic against them.", sourceObjectiveStatus = "unverified-source-field" }
quests[10671] = { id = 10671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More than a Pound of Flesh", description = "{name}, I've got something else for you to do.  One of the eggheads wants to study the fiendling flesh beasts that can be found at Razaan's Landing, north of the Razor Ridge.\n\nMore to the point, they want to study the flesh of the flesh beasts that are there.\n\n<Dizzy makes a disgusted face.>\n\nBut, of course, they aren't willing to get their hands dirty, and they only want the ether-energized flesh, which it's not likely that all of them have.\n\nI say, beggars can't be choosers, but what can you do?", sourceObjective = "Collect 5 Ether-Energized Flesh.", progress = "You have my pound of flesh?  What, you didn't think that was funny?", completion = "These ought to do nicely.  Don't they stink, though?\n\nI hope that this is worth your troubles... I'm just glad that it was you collecting this stuff instead of me!", sourceObjectiveStatus = "unverified-source-field" }
quests[10672] = { id = 10672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frankly, It Makes No Sense...", description = "We must study these creatures further.\n\nFar to the east - near the huge lava flow beneath the ruins of Baa'ri - you will find arcano control units. These controllers were crafted by a genius named Gnomus for the sole purpose of exploring lava via mechanical scorpion.\n\nHe has long since lost his mind and is now only interested in eating the hottest food known to gnome-kind.\n\n<Tiorus gives you a funny look.>\n\nI want you to use the control and tag the diemetradons of the lava flow for further study.", sourceObjective = "Researcher Tiorus at Shadowmoon Village in Shadowmoon Valley wants you to travel to the lava flow near the Ruins of Baa'ri and use the Arcano Control Unit to control an Arcano-Scorp, swim in the lava with the Arcano-Scorp, and tag 8 Greater Felfire Diemetradons.", completion = "Listen, there is no time to spare. I've been watching the tagged diemetradons and have discovered that they all report to a gigantic, nay, ENORMOUS, diemetradon named Felspine the Greater.", sourceObjectiveStatus = "unverified-source-field" }
quests[10673] = { id = 10673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felspine the Greater", description = "Gnomus knows about the massive diemetradon and plans to eat it! He must have been able to see what I could see through the eyes of his arcano-scorp. Look, there's no time to explain. He's crazy and that craziness is going to cost us the closest thing we've got to a fireproof jumpsuit.\n\nGet back to the lava flow near Baa'ri and track down Felspine the Greater. Once you find it, kill it and bring me back its hide.\n\nDon't try and reason with me, {name}. I'm well past that point.", sourceObjective = "Researcher Tiorus at Shadowmoon Village in Shadowmoon Valley wants you to kill Felspine the Greater and recover Felspine's Hide.", progress = "Snap to it! That gnome's appetite knows no limit!", completion = "At last! Total protection against lava is mine! Of course you get a cut of this technology too, {name}. You've earned it!", sourceObjectiveStatus = "unverified-source-field" }
quests[10674] = { id = 10674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trapping the Light Fantastic", description = "The Razaani ethereals have been playing with some interesting technology at Razaan's Landing to the north.\n\nI'm sure they won't mind if you use this trap to take a few samples of their little pink floating light orbs?  They're probably only for decoration anyway.\n\nThe trap has a special property to it that when opened should attract one of the floating balls towards it.  Of course, it'll probably also alert the Razaani to your presence.", sourceObjective = "Use the Light Trap to collect 15 Razaani Light Orbs.", progress = "I take it that since we're speaking, you have the light orbs from the Razaan's Landing?  It'll be interesting to take a look at them and see what the ethereal are up to.", completion = "Hey!  Wait just one damned minute!!\n\nThis doesn't look good...", sourceObjectiveStatus = "unverified-source-field" }
quests[10675] = { id = 10675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Show Them Gnome Mercy!", description = "<The blood drains out of Toshley's face.>\n\nThese orbs are made up of both nether energy and souls, some of them gnome souls!\n\nHow dare they!  Were they the ones killing our people that traveled north?!\n\n{name}, you must put a stop to this, and the only way to do that is to finish off their leader, Nexus-Prince Razaan.\n\nYou'll have to coax him out of hiding though.  I'm guessing that you can do that by killing a lot of his Razaani ethereal.\n\nBring me the collection of souls that he no doubt has.", sourceObjective = "Collect the Collection of Souls.", progress = "Have you dealt with that soul-stealing bastard, Razaan yet?", completion = "Good riddance to him!  Thank you for putting an end to their macabre twisting of magic and technology.\n\nAs a true hero of gnomes everywhere, I hereby bequeath unto you our highest honor... some power converters and your pick of any of these.\n\nI know that you'll put them to good use!", sourceObjectiveStatus = "unverified-source-field" }
quests[10676] = { id = 10676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bane of the Illidari", description = "<David gathers his smithing supplies.>\n\nYou've done well in getting everything we'll need to reforge the anti-demon blade. Your hard work and dedication is about to be repaid.\n\nThe time has come to forge the sword.", sourceObjective = "Wait for David Wayne to finish forging a sword for you.", completion = "<David mops sweat from his brow.>\n\nThe bulk of the work is done, but to set the magics, the blade must now be quenched.", sourceObjectiveStatus = "unverified-source-field" }
quests[10677] = { id = 10677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Second Course...", description = "I remember seeing larger diemetradons east of the Hand of Gul'dan, near the lava flows around the Ruins of Baa'ri. What I want you to get for me now is one overdeveloped felfire gizzard from the beasts around that area. You might have to kill several to find a gizzard like the one I described. Keep at it! One of them is bound to have my next meal.", sourceObjective = "Gnomus at Wildhammer Stronghold in Shadowmoon Valley wants you to recover 1 Overdeveloped Felfire Gizzard.", progress = "Special of the day: Gizzard.", completion = "This is fantastic but I just received some incredible news!", sourceObjectiveStatus = "unverified-source-field" }
quests[10678] = { id = 10678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Main Course!", description = "Long story short, I used to work with a blood elf named Tiorus. My partnership with Tiorus dissolved once I got into gourmet living. He decided to take it upon himself to continue our research using MY inventions. Anyhow, he had some of his Horde goons using my arcano-scorp probes at the Ruins of Baa'ri lava flow and discovered the mother of all diemetradons!\n\nI need you to get there before he does and kill the diemetradon, Felspine, and bring his hide back to me.\n\nHurry up!", sourceObjective = "Gnomus at Wildhammer Stronghold in Shadowmoon Valley wants you to recover Felspine's Hide.", progress = "Special of the day: Felspine's hide.", completion = "I'll need some alone time now, {name}. Thanks for all the help!", sourceObjectiveStatus = "unverified-source-field" }
quests[10679] = { id = 10679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quenching the Blade", description = "The blade is nearly finished!\n\nYou can almost feel the magic beginning to coalesce inside the steel, but one thing remains to be done.\n\nYou must take the forged blade to the Scalding Pools near the top of the Hand of Gul'dan in Shadowmoon Valley and plunge it into the lava pools to quench the sword. When you have quenched the sword, return.", sourceObjective = "Travel to the Scalding Pools located near the top of the Hand of Gul'dan and use the Forged Illidari-Bane Blade to quench it in the lava pools. Once you have the Quenched Illidari-Bane Blade, return to David Wayne at Wayne's Refuge.", progress = "Have you quenched the sword in the lava of the Hand of Gul'dan?", completion = "Well done!\n\n<The smith examines the blade closely.>\n\nI'd say it's a fair improvement over the crude Legion weapons you started with. Not only will this blade cut down Illidari demons, but it will work against the Legion's minions as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[10680] = { id = 10680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hand of Gul'dan", description = "The elements need your help, {race}! Shadowmoon Valley has been subject to unspeakable evils. The spirits remain tortured to this day. Many are enraged and unwilling to commune with the Earthen Ring.\n\nHelp this world heal, friend.\n\nDirectly northeast of Wildhammer Stronghold you will find an area known as the Altar of Damnation. Make your way there and speak with Earthmender Torlok.", sourceObjective = "Speak with Earthmender Torlok at the Altar of Damnation in Shadowmoon Valley.", completion = "It is good that you came, {race}. We have much work to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[10681] = { id = 10681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hand of Gul'dan", description = "The elements need your help, {race}! Shadowmoon Valley has been subject to unspeakable evils. The spirits remain tortured to this day. Many are enraged and unwilling to commune with the Earthen Ring.\n\nHelp this world heal, friend.\n\nSoutheast of Shadowmoon Village - in the heart of Shadowmoon Valley - you will find an area known as the Altar of Damnation. Make your way there and speak with Earthmender Torlok.", sourceObjective = "Speak with Earthmender Torlok at the Altar of Damnation in Shadowmoon Valley.", completion = "It is good that you came, {race}. We have much work to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[10682] = { id = 10682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Time for Negotiation...", description = "When we arrived in the Ruuan Weald, the wyrm cultists were keeping themselves to Blackwing Coven, through the tunnel to the west.  But now, they are encroaching upon us here.\n\nI need you to find the wyrmcultists' overseer.  He's known to make a regular patrol between their various camps in the Ruuan Weald.\n\nNegotiate with him.  Let him know that there's room for compromise, but that we will not condone or allow the wholesale slaughter of the wildlife, nor the felling of all of the trees.", sourceObjective = "Negotiate with Overseer Nuaar.", progress = "Is everything okay?", completion = "WHAT?!  They dismissed you and our proposals out of hand?\n\nThis is outrageous!  We go to them in good faith, and they turn you away without even trying to come to a compromise?\n\nWell, we'll see about that!", sourceObjectiveStatus = "unverified-source-field" }
quests[10683] = { id = 10683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tablets of Baa'ri", description = "The Ashtongue Broken have been ordered by Illidan to excavate the Ruins of Baa'ri, to the far north.  They're in search of draenei artifacts, no doubt - Baa'ri was home to many Baa'ri relics before Gul'dan buried the town under a volcanic explosion.  We must use this opportunity to recover the Tablets of Baa'ri, an ancient text rumored to hold the secrets of the Temple of Karabor... a place you might know as the Black Temple.", sourceObjective = "Arcanist Thelis at the Sanctum of the Stars wants you to collect 12 Baa'ri Tablets from the ground and from Ashtongue Workers at the Ruins of Baa'ri.\n\nCompleting quests with the Scryers will cause your Aldor reputation level to decrease.", progress = "Have you found the tablets yet, {name}?", completion = "The Baa'ri tablets!  Yes, this might provide us with very useful information.", sourceObjectiveStatus = "unverified-source-field" }
quests[10684] = { id = 10684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oronu the Elder", description = "According to the tablets, an artifact known as a Medallion of Karabor was kept at Baa'ri.  Only the highest-ranking draenei priests were granted these, as they allowed unfettered access into the Temple of Karabor.\n\nWe must find out whether the Ashtongue have recovered the medallion that was kept at Baa'ri yet.  Its power would provide great aid in our fight against Illidan.\n\nAkama's lieutenant at Baa'ri, Oronu the Elder, receives written orders from him daily.  Obtain them and bring them to me.", sourceObjective = "Arcanist Thelis at the Sanctum of the Stars wants you to obtain the Orders from Akama from Oronu the Elder at the Ruins of Baa'ri.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "Any news yet, {name}?  Time is not on our side.", completion = "It matches Akama's handwriting... let us see what we can learn.", sourceObjectiveStatus = "unverified-source-field" }
quests[10685] = { id = 10685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ashtongue Corruptors", description = "According to Akama's letter, four fragments of the medallion were unearthed and given to the Ashtongue Corruptors.  These dreaded Broken were once powerful shaman who now defile the very elements they revered.\n\nHaalum, Corruptor of Air, can be found at Netherwing Pass.  Eykenen and Uylaru, Corruptors of Earth and Fire, were last seen at the Fel Pits near the Hand of Gul'dan.  Lakaan, Corruptor of Water, is rumored to be near Coilskar Point.\n\nFind them and obtain the medallion fragments.", sourceObjective = "Obtain the four medallion fragments from Haalum, Eykenen, Lakaan and Uylaru and return to Arcanist Thelis at the Sanctum of the Stars in Shadowmoon Valley.\n\nPerforming quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "Have you obtained the four medallion fragments, {name}?", completion = "Yes!  The four fragments of the medallion.  Now to put them together...", sourceObjectiveStatus = "unverified-source-field" }
quests[10686] = { id = 10686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden's Cage", description = "The fragments you obtained are only half of the medallion.  The Ashtongue leader, Akama, must have kept the other half.\n\nI dread to ask this of you, as Akama is both evil and cunning.\n\nHe and the Ashtongue Deathsworn - the vilest and most brutal of the tribe - are rumored to run a torture chamber inside the Warden's Cage.\n\nI want you to find that dreaded prison,  and find the whereabouts of Akama.  His second in command at the location is a Broken known as Sanoru - interrogate him if you have to.", sourceObjective = "Arcanist Thelis wants you to enter the Warden's Cage, south of the Ruins of Baa'ri and interrogate Sanoru on Akama's whereabouts.\n\nCompleting quests for the Scryers will cause your Aldor reputation to decrease.", completion = "We've been expecting you, {name}.  Akama said you would arrive sooner or later.", sourceObjectiveStatus = "unverified-source-field" }
quests[10687] = { id = 10687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karabor Training Grounds", description = "Our scouts have reported a massive influx of Sunfury blood elf recruits heading to the Ruins of Karabor.  Normally this would represent a purely military threat, however we believe something else is amiss.\n\nDescriptions of their attire and fighting style are suspiciously close to that of Illidan himself.  I do not want to become alarmed without good reason, so I would like you to go there and bring me back their weapons.  We will then determine whether my fears are unfounded or not.", sourceObjective = "Larissa Sunstrike at the Sanctum of the Stars wants you to obtain 8 Sunfury Glaives from the Demon Hunter Supplicants and Demon Hunter Initiates at the Ruins of Karabor, northeast of the Sanctum of the Stars.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "Have you completed the task I asked of you, {name}?", completion = "Let's take a closer look at these weapons, {name}.  Hmmm... this is rather unsettling.", sourceObjectiveStatus = "unverified-source-field" }
quests[10688] = { id = 10688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Necessary Distraction", description = "The weapons are authentic, as we feared.  Illidan is training demon hunters at the Ruins of Karabor and we must put an end to it.\n\nDo not be fooled by their name, {name}, their power will be used against us as often as against any demon.\n\nTheir warlocks summon and subdue demons to be used as part of the initiates' training.  A pit lord named Azaloth has proven too strong to be used in training and is kept banished.  Find a way to let him loose on his captors.  That should buy us the time we need.", sourceObjective = "Larissa Sunstrike wants you to return to the Ruins of Karabor and find a way to unleash Azaloth on his captors.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", completion = "That should buy us some time... hopefully it will be enough for us to obtain more information.", sourceObjectiveStatus = "unverified-source-field" }
quests[10689] = { id = 10689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Altruis", description = "You don't see many demon hunters nowadays.  They're viewed with suspicion by their own people and it's very rare to find one that doesn't have some sort of allegiance to Illidan.\n\nThere are rumors of one such demon hunter out in Nagrand.  His name is Altruis.  He hates all demons with a passion and will help us if you can convince him that you share his goals.\n\nGo to western Nagrand and find him.  He might be willing to shed some light on these new demon hunter training grounds.", sourceObjective = "Travel to western Nagrand and find Altruis the Sufferer.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", completion = "You've come a long way, stranger.  I'm surprised whoever sent you has heard of me.", sourceObjectiveStatus = "unverified-source-field" }
quests[10690] = { id = 10690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Den Mother", description = "WANTED!\n\nRema, the den mother and primary defender of the Jagged Ridge south of Thunderlord Stronghold.\n\nFind her by heading east out of town and across the bridge that traverses the Bloodmaul Ravine.  She keeps herself secluded in the tunnel at the southern edge of the ridge.\n\nReturn with news of her demise to Commander Skyshadow of Sylvanaar.", sourceObjective = "Slay Rema.", progress = "What can I do for you today?", completion = "Unbelievable.  Did you slay Rema all by yourself?\n\nBy the looks of you, I'd say that you could.  You know, we're looking for a young, strong {class}, such as yourself, to help out around here, especially with the problems we continually have with the ogres.  Make sure that you follow-up with me on that possibility.\n\nWell, you've definitely earned the bounty that I put on that wanted poster.\n\nPlease, take your pick.", sourceObjectiveStatus = "unverified-source-field" }
quests[10691] = { id = 10691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Scryers", description = "This book... I could use it to increase my power tenfold...  No!  It would end up corrupting my very soul, this I am sure of.  Return to those who sent you here, {name}.\n\nYou now have the means to stop Varedis.  Wait until he manifests his demonic form through metamorphosis, at that point you will need to burn the book in his presence.  That will be the only way you can deprive him of his power.", sourceObjective = "Speak with Larissa Sunstrike at the Sanctum of the Stars in Shadowmoon Valley.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", completion = "Many would pay a great price for the book you carry with you.  It is a shame we'll have to destroy it.", sourceObjectiveStatus = "unverified-source-field" }
quests[10692] = { id = 10692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varedis Must Be Stopped", description = "Of course we must destroy this book, but not before we use it to destroy Varedis.\n\nIf we're to shut down this academy of Illidan imitators, we'll have to deal not just with Varedis but also the three night elf masters that assist him: Alandien, Theras and Netharel.\n\nGather a suitable force and return to the Ruins of Karabor.  Follow Altruis's instructions for defeating Varedis.  Hopefully his plan will work - otherwise... it'll have been a pleasure working with you.", sourceObjective = "Larissa Sunstrike wants you to go to the ruins of Karabor and slay Alandien, Theras, Netharel and Varedis. Use the Book of Fel Names when Varedis uses Metamorphosis to weaken him. Return to Larissa Sunstrike with the Book of Fel Names after completing this task.\n\nCompleting quests for the Scryers will cause your Aldor reputation to decrease.", progress = "Have you completed what I asked of you, {name}?", completion = "You've done well, {name}.  By slaying Varedis you've put an end to one of Illidan's most dangerous projects.\n\nYour name will definitely get around after this.\n\nAllow me to take what remains of the Book of Fel Names.  I will make sure it's properly... disposed of.", sourceObjectiveStatus = "unverified-source-field" }
quests[10693] = { id = 10693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Commendation Signet" }
