quests[10729] = { id = 10729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of the Violet Mage", sourceObjective = "Are you certain of your choice, {name}?  This is not a decision you ought to take lightly.\n\nThe Violet Signet will grow in power as you continue to prove yourself to the Violet Eye.", sourceObjectiveStatus = "unverified-source-field" }
quests[10730] = { id = 10730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of the Violet Restorer", sourceObjective = "Are you certain of your choice, {name}?  This is not a decision you ought to take lightly.\n\nThe Violet Signet will grow in power as you continue to prove yourself to the Violet Eye.", sourceObjectiveStatus = "unverified-source-field" }
quests[10731] = { id = 10731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of the Violet Assassin", sourceObjective = "Are you certain of your choice, {name}?  This is not a decision you ought to take lightly.\n\nThe Violet Signet will grow in power as you continue to prove yourself to the Violet Eye.", sourceObjectiveStatus = "unverified-source-field" }
quests[10732] = { id = 10732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of the Violet Protector", sourceObjective = "Are you certain of your choice, {name}?  This is not a decision you ought to take lightly.\n\nThe Violet Signet will grow in power as you continue to prove yourself to the Violet Eye.", sourceObjectiveStatus = "unverified-source-field" }
quests[10733] = { id = 10733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down the Violet Path", description = "You've chosen your path, {class}.  Now it is up to you to travel the path to wherever it may lead.\n\nYou will find that having friends among the Archmages of Dalaran has its advantages.  Serve us well and your deeds will not go unrewarded.", sourceObjective = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Honored reputation with the Violet Eye.", progress = "It is good to see you again, {name}.", completion = "You honor us with your service, {name}.  Behold as I unleash the power contained in your signet!", sourceObjectiveStatus = "unverified-source-field" }
quests[10734] = { id = 10734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down the Violet Path", description = "You've chosen your path, {class}.  Now it is up to you to travel the path to wherever it may lead.\n\nYou will find that having friends among the Archmages of Dalaran has its advantages.  Serve us well and your deeds will not go unrewarded.", sourceObjective = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Honored reputation with the Violet Eye.", progress = "It is good to see you again, {name}.", completion = "You honor us with your service, {name}.  Behold as I unleash the power contained in your signet!", sourceObjectiveStatus = "unverified-source-field" }
quests[10735] = { id = 10735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down the Violet Path", description = "You've chosen your path, {class}.  Now it is up to you to travel the path to wherever it may lead.\n\nYou will find that having friends among the Archmages of Dalaran has its advantages.  Serve us well and your deeds will not go unrewarded.", sourceObjective = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Honored reputation with the Violet Eye.", progress = "It is good to see you again, {name}.", completion = "You honor us with your service, {name}.  Behold as I unleash the power contained in your signet!", sourceObjectiveStatus = "unverified-source-field" }
quests[10736] = { id = 10736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down the Violet Path", description = "You've chosen your path, {class}.  Now it is up to you to travel the path to wherever it may lead.\n\nYou will find that having friends among the Archmages of Dalaran has its advantages.  Serve us well and your deeds will not go unrewarded.", sourceObjective = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Honored reputation with the Violet Eye.", progress = "It is good to see you again, {name}.", completion = "You honor us with your service, {name}.  Behold as I unleash the power contained in your signet!", sourceObjectiveStatus = "unverified-source-field" }
quests[10737] = { id = 10737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master's Touch", description = "I've put together the very key I used as an apprentice.  It looks completely functional as far as keys go.  In regards to opening Karazhan, however, this might as well be a piece of scrap metal.\n\nWithout Medivh's consent, the key is worthless.  Yes, of course I know Medivh is dead.  This merely makes things difficult, not impossible\n\nThere is a place in Azeroth called the Caverns of Time, guarded by the bronze dragonflight.  Find a way inside, travel back in time and get Medivh to enable the key.", sourceObjective = "Go into the Caverns of Time and convince Medivh to enable your Restored Apprentice's Key.", sourceObjectiveStatus = "unverified-source-field" }
quests[10738] = { id = 10738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distinguished Service", description = "You have not disappointed us, {name}.  We continue to have very high hopes for you, however.\n\nContinue to serve the Violet Eye and you will be appropriately rewarded.", sourceObjective = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Revered reputation with the Violet Eye.", progress = "You're welcome among us, as always.  What brings you to us?", completion = "Your services have not gone unnoticed, {name}.  Your signet may look the same, but its powers grow as you continue to prove your loyalty.", sourceObjectiveStatus = "unverified-source-field" }
quests[10739] = { id = 10739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distinguished Service", description = "You have not disappointed us, {name}.  We continue to have very high hopes for you, however.\n\nContinue to serve the Violet Eye and you will be appropriately rewarded.", sourceObjective = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Revered reputation with the Violet Eye.", progress = "You're welcome among us, as always.  What brings you to us?", completion = "Your services have not gone unnoticed, {name}.  Your signet may look the same, but its powers grow as you continue to prove your loyalty.", sourceObjectiveStatus = "unverified-source-field" }
quests[10740] = { id = 10740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distinguished Service", description = "You have not disappointed us, {name}.  We continue to have very high hopes for you, however.\n\nContinue to serve the Violet Eye and you will be appropriately rewarded.", sourceObjective = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Revered reputation with the Violet Eye.", progress = "You're welcome among us, as always.  What brings you to us?", completion = "Your services have not gone unnoticed, {name}.  Your signet may look the same, but its powers grow as you continue to prove your loyalty.", sourceObjectiveStatus = "unverified-source-field" }
quests[10741] = { id = 10741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distinguished Service", description = "You have not disappointed us, {name}.  We continue to have very high hopes for you, however.\n\nContinue to serve the Violet Eye and you will be appropriately rewarded.", sourceObjective = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Revered reputation with the Violet Eye.", progress = "You're welcome among us, as always.  What brings you to us?", completion = "Your services have not gone unnoticed, {name}.  Your signet may look the same, but its powers grow as you continue to prove your loyalty.", sourceObjectiveStatus = "unverified-source-field" }
quests[10742] = { id = 10742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Showdown", description = "Now it comes to this. We will bring Goc forth from his lair, and we will destroy him. With Goc dead, the Bladespire ogres will threaten the Mok'Nathal no longer. Go to Goc's altar outside Gruul's Lair, then blow my horn. I will come, and we will face the son of Gruul together.", sourceObjective = "Use Rexxar's Battle Horn at the Altar of Goc, then kill Goc.", progress = "Only through the deaths of Goc and Gorgrom the Dragon-Eater will we free the Mok'Nathal.", completion = "The battle was hard and you fought well, {name}. I am honored to have stood by your side in the battle against Goc. I am thankful beyond words.\n\nThe Mok'Nathal should know of these great defeats, but I am not ready to face them yet. I know my father's mind, and I know my heart. There is still much I can learn and do to become stronger, to show to him that I am his true son.", sourceObjectiveStatus = "unverified-source-field" }
quests[10744] = { id = 10744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News of Victory", description = "You must bring word of our success to Kurdran Wildhammer immediately! His men, under Wing Commander Nuainn, have fought nonstop to keep Wildhammer Stronghold safe and your return will surely bolster their spirits. With the threat from the Legion out of the way, Kurdran can finally turn his attention to dealing with the forces of Illidan. Our place here is far from secure, but we've won a major victory this day.", sourceObjective = "Return to Wildhammer Stronghold and speak with Kurdran Wildhammer.", completion = "<Kurdran listens to your report.>\n\nThat is good news, indeed! Mere days ago, I wouldn't have dreamt that we could break the Legion's siege on the stronghold.\n\nNot only have you halted their offensive, but you've broken the back of their war machine as well! You have the gratitude of the Wildhammer clan for your valor, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10745] = { id = 10745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News of Victory", description = "You must bring word of our success to Overlord Or'barokh immediately! Now that we've crushed the Legion and obliterated their presence in Shadowmoon Valley, the overlord can turn his attention to our other foes.\n\nAlthough the Kor'kron guard will never admit it, they'll be glad we're no longer fighting on two fronts.", sourceObjective = "Return to Shadowmoon Village and speak with Overlord Or'barokh.", completion = "<The overlord listens to your report.>\n\nExcellent news! Holding the line against the Legion's infernals was taking too many resources. Not that I expected my men to break, but they were greatly strained.\n\nYou have proven your worth to the Horde this day. The Kor'kron guard would be honored to fight by your side anytime.", sourceObjectiveStatus = "unverified-source-field" }
quests[10747] = { id = 10747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whelps of the Wyrmcult", description = "I need to examine the whelps that they are raising at the Blackwing Coven.\n\nThere should be an abundance of them flying around inside their cavernous base, as well as a number of eggs, which if you get close to them will likely hatch.\n\nPlease, {name}, take the net and capture a handful of them alive for me.\n\nFind them by heading west across the Wyrmskull Bridge and heading through the Wyrmskull Tunnel.  Follow the path to its end past Grishnath and the Raven's Wood.", sourceObjective = "Use the Blackwhelp Net to capture 10 Wyrmcult Blackwhelps.", progress = "Did you run into much trouble snatching the whelps?  I hope you didn't get singed!", completion = "Oh my goodness, these are more than I'd hoped for!  You are certainly to be lauded for your heroics!\n\nThis looks like a fine brood of blackwhelps to make a start with.  Examining them, that is.\n\nPlease, accept this as payment.  I insist!", sourceObjectiveStatus = "unverified-source-field" }
quests[10748] = { id = 10748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maxnar Must Die!", description = "They've left us no choice, {name}.  It's time to put an end to the threat from the Blackwing Coven by taking out their leader, Maxnar the Ashmaw.\n\nI don't know if you caught a glimpse of him while you were in there, but he's one of the dragonkin, half-man, half-dragon.  And he's tough, so don't underestimate him!\n\nFinish it quickly and with any luck you'll secure the safety of Evergrove and the Ruuan Weald.", sourceObjective = "Slay Maxnar the Ashmaw.", progress = "You've dealt with Maxnar the Ashmaw already?\n\nAre you having trouble finding him?  As I understand it if you head to the right once you enter their caverns, it will eventually curve around and lead you to him.", completion = "Now we can breathe more easily knowing that the leader of our enemy has been dealt with.  Not only that, but you've saved the entire mountain range from their depredations.\n\nWhatever their ultimate goals, you've foiled them!\n\nYou have our gratitude, {name}.  Please accept this token of our esteem, as well as our unending hospitality.", sourceObjectiveStatus = "unverified-source-field" }
quests[10749] = { id = 10749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Sablemane's Poison", description = "Here, take this to your master. I'm sure that whatever the reason, Rexxar will put it to good use.\n\nOh, and do be certain to remind him that he owes me.\n\nHe knows what I want, and I'm certain that however he intends to obtain it for me, I'll be seeing you again sooner than you think.\n\nNow, do be a good little <boy/girl> and run this up to Rexxar.", sourceObjective = "Deliver Baron Sablemane's Poison to Rexxar at Thunderlord Stronghold in the Blade's Edge Mountains.", progress = "{class}, you are back so soon? Do you have the poison?", completion = "This is unsavory business, this use of poisons. But it will do what we want.", sourceObjectiveStatus = "unverified-source-field" }
quests[10750] = { id = 10750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of Conquest", description = "Word has come from my wind riders, {name}. The Eclipsion blood elves are planning something big. They have begun forming their armies at the Path of Conquest, far to the southeast - adjacent to Eclipse Point.\n\nI want you to travel to the Path of Conquest and assess the situation. Once you have done so, use this flare gun to signal a wind rider. One will swoop down from the sky to meet you. Inform them of what you have discovered and they will give you your next set of orders.", sourceObjective = "Travel to the Path of Conquest in Shadowmoon Valley.", progress = "What have you to report, soldier?", completion = "Indeed, these troublesome whelps are up to something insidious. We must investigate further...", sourceObjectiveStatus = "unverified-source-field" }
quests[10751] = { id = 10751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaching the Path", description = "We're going to need more time, {race}. I'm going to fly further ahead with some of the other wind riders. Hopefully, we can gather some more information. What I need from you now is to clear a path and more importantly, keep their arrows pointed away from us!\n\nCall for a wind rider with the Kor'kron flare gun once you have thinned their numbers.", sourceObjective = "Slay 20 Eclipsion Soldiers, 10 Eclipsion Cavaliers, and 10 Eclipsion Spellbinders.", progress = "What have you to report, soldier?", completion = "You won't believe this, grunt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10752] = { id = 10752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onward to Ashenvale", description = "Recently Raene Wolfrunner came through Auberdine from Darnassus and was heading to Ashenvale; she said something about the Furbolgs. I wasn't given an opportunity to ask more about her situation but perhaps you can seek her out and lend her your aid {class}. Take the southern road out of Auberdine. Once you reach Ashenvale border continue your path down the road. There you will find Astranaar and Raene Wolfrunner.", sourceObjective = "Speak with Raene Wolfrunner in Astranaar.", completion = "So Thundris Windweaver still thinks I need looking after? I'll need to remind him who saved whom; he seems to forget it was I that pulled him from harm's way.\n\nWell now that you're here, {race}, perhaps I can find something for you to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[10753] = { id = 10753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Wild", description = "The number of atrocities committed by the Burning Legion is countless. Even as we speak, they send their legion forces against the creatures of this land. Helpless to defend against their power, they fall one by one. {name}, help me stop these crimes of nature destroy all which they corrupt. \n\nOver the hill, east of here, you will see the corruption spreading across Bladed Gulch. Kill the ones causing the crime, the Fel Corrupters, and as many Felsworn as you can.", sourceObjective = "Slay 4 Felsworn Scalewing, 4 Felsworn Daggermaw, and 2 Fel Corrupters.", completion = "I do not pride myself knowing we destroyed what Elune has created, but the corruption needed to be stopped. You have done well {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10754] = { id = 10754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entry Into the Citadel", description = "This freshly cast mold was to be used to create a key of some sort.  From the image engraved on its back, it appears to be related to Hellfire Citadel.\n\nMaybe this could prove to interest to Danath, the force commander at Honor Hold.", sourceObjective = "Bring the Primed Key Mold to Force Commander Danath at Honor Hold in Hellfire Peninsula.", progress = "You've something to show me, {name}?", completion = "Could this be?  Let me take a closer look at that mold.", sourceObjectiveStatus = "unverified-source-field" }
quests[10755] = { id = 10755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entry Into the Citadel", description = "This freshly cast mold was to be used to create a key of some sort.  From the image engraved on its back, it appears to be related to Hellfire Citadel.\n\nMaybe this could prove to interest to Nazgrel, the leader of the Horde's forces in Thrallmar.", sourceObjective = "Bring the Primed Key Mold to Nazgrel at Thrallmar in Hellfire Peninsula.", progress = "You've something to show me, {name}?", completion = "A key mold?  Could this be what grants us access to the Shattered Halls?", sourceObjectiveStatus = "unverified-source-field" }
quests[10756] = { id = 10756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Rohok", description = "The symbol on the key's handle... it is hard to make it out inside the mold, but I recognize it as the Shattered Hand's own.\n\nThere is a good chance this key will allow you to enter the Shattered Halls.\n\nSpeak to Rohok, our resident blacksmith.  If anyone can forge this key it is he.", sourceObjective = "Bring the Primed Key Mold to Rohok at Thrallmar in Hellfire Peninsula.", progress = "What is this?", completion = "Nazgrel wants me to work on a key?  Does he forget we're in a battlefield?  There are blades and spears to forge!", sourceObjectiveStatus = "unverified-source-field" }
quests[10757] = { id = 10757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohok's Request", description = "Fel orc blacksmiths may not be the most skilled in the world, but there is some craftsmanship to their trade.  Only fel iron can be used with this mold if we want to end up with a working key - anything else would probably end up breaking it.\n\nBring me some fel iron bars, a bit of arcane dust and motes of fire.  I'll try my hand at it, but I make no promises.", sourceObjective = "Bring 4 Fel Iron Bars, 2 Arcane Dust and 4 Motes of Fire to Rohok at Thrallmar in Hellfire Peninsula.", progress = "Have you obtained the materials I requested?", completion = "Excellent.  Let's give it a shot.", sourceObjectiveStatus = "unverified-source-field" }
quests[10758] = { id = 10758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hotter than Hell", description = "It's no good, {name}!  No matter how many coals I put to the fire, it's just not enough heat.\n\nThere's only one thing I can think of that is hot enough to temper this key and it is the insides of the Legion's fel reavers.\n\nI've only ever seen one downed once.  I remember seeing its insides fuming, shooting fire and steam as it fell.  Take this mold and plunge it into a fallen fel reaver.  I recommend you get yourself some friends if you plan to take one down.", sourceObjective = "Destroy a Fel Reaver in Hellfire Peninsula and plunge the Unfired Key Mold into its remains. Bring the Charred Key Mold to Rohok in Thrallmar.", progress = "Did you do what I asked of you, {class}?", completion = "You've succeeded!  Only thing left for you to do is try it out.", sourceObjectiveStatus = "unverified-source-field" }
quests[10759] = { id = 10759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find the Deserter", description = "I get the feeling that all the pieces are here, but I just can't put them together in a way that makes sense.\n\nI think our best lead is to attempt to locate this deserter. If he left his comrades at the camp, there's a chance you might be able to persuade him to help us understand what the dark conclave arakkoa are planning.\n\nStart your search for him along the road in Magma Fields to the northwest. It seems a likely place for him to take refuge.", sourceObjective = "Locate Parshah in the Magma Fields and speak to him.", completion = "<The arakkoa cackles.>\n\nYes, I am the deserter mentioned in the commander's journal. I have been waiting for the day when others might recognize the threat posed by those I once called brothers.", sourceObjectiveStatus = "unverified-source-field" }
quests[10760] = { id = 10760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sketh'lon Wreckage", description = "The Sketh'lon Wreckage, just to the east, is an eerie place. The peons are convinced that it's cursed.\n\nThere are few trees here, so the peons have no choice but to venture into the arakkoa ruins to chop wood. The arakkoa spirits prey on the work groups, draining their life and using it to fuel their foul magics.\n\nWe must find out what is driving the dark conclave and stop them before their influence expands. Search the Sketh'lon Wreckage for evidence of their plans.", sourceObjective = "Recover the Skethlon Commander's Journal Page 1, Skethlon Commander's Journal Page 2, and Skethlon Commander's Journal Page 3 from the Dark Conclave arakkoa at the Sketh'lon Wreckage to Sergeant Kargrul at Shadowmoon Village.", progress = "What have you discovered?", completion = "<The sergeant examines the journal pages.>\n\nI don't see much of use here, but there are a couple of entries that could prove useful. It looks as though these arakkoa were preparing some kind of elaborate magical ritual up until the time of their deaths, but why? There's also a curious note here about a 'deserter.'", sourceObjectiveStatus = "unverified-source-field" }
quests[10761] = { id = 10761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find the Deserter", description = "There's nothing here that would explain why the spirits of these arakkoa have remained in this world or how they came into thirst for the blood of orcs.\n\nI think our best lead is to try to find the deserter mentioned in the journal. If he left his comrades at the camp, there's a chance you might be able to persuade him to help us understand what the dark conclave arakkoa are planning.\n\nStart your search for him on the road through the Magma Fields to the southeast.", sourceObjective = "Locate Parshah in the Magma Fields and speak to him.", completion = "<The arakkoa cackles.>\n\nYes, I am the deserter mentioned in the commander's journal. I have been waiting for the day when others might recognize the threat posed by those I once called brothers.", sourceObjectiveStatus = "unverified-source-field" }
quests[10762] = { id = 10762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Dumphry", description = "The symbol on the key's handle... it is hard to make it out inside the mold, but I recognize it at the Shattered Hand's own.\n\nThere is a good chance this key will allow you to enter the Shattered Halls.\n\nSpeak to Dumphry.  He is a master of his craft.  If he can't craft this key for you, no one can.", sourceObjective = "Bring the Primed Key Mold to Dumphry in Honor Hold.", progress = "What is this?", completion = "A key?  Danath should have us working on siege engines!", sourceObjectiveStatus = "unverified-source-field" }
quests[10763] = { id = 10763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dumphry's Request", description = "Fel orcs might be complete barbarians but their smithing is not as primitive as you might think.  Only fel iron can be used with this mold if we want to end up with a working key - anything else would probably end up breaking it.\n\nBring me some fel iron bars, a bit of arcane dust and motes of fire.  I'll try my hand at it, but I make no promises.", sourceObjective = "Bring 4 Fel Iron Bars, 2 Arcane Dust and 4 Motes of Fire to Dumphry at Honor Hold in Hellfire Peninsula.", progress = "Have you obtained the materials I requested?", completion = "Let's try it then.  Let's see what fel orc crafting is all about.", sourceObjectiveStatus = "unverified-source-field" }
quests[10764] = { id = 10764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hotter than Hell", description = "It's not working, <lad/lass>.  I cannot give it enough heat... the materials will not be properly tempered.\n\nYou know, the fel reavers used by the Burning Legion are powered by a scalding core of fel fire - it burns much hotter than normal fire.\n\nIf you could find enough people to take one down, you could heat the mold in the insides of the fallen reaver.  Beware, {class}, those fel reavers pack quite a punch.", sourceObjective = "Destroy a Fel Reaver in Hellfire Peninsula and plunge the Unfired Key Mold into its remains. Bring the Charred Key Mold to Dumphry in Honor Hold.", progress = "Did you do what I asked of you, {class}?", completion = "You've done it, laddie!  Only thing left to do is for you to take it to Hellfire Citadel and kill yourself some orcs!", sourceObjectiveStatus = "unverified-source-field" }
quests[10765] = { id = 10765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Worlds Collide...", description = "At the southern end of the Path of Conquest, near a stationary caravan, I discovered what looked like a meeting between a giant and a blood elf chancellor. You've probably already noticed the smaller giants on the path as well. Something is just not right about all of this, grunt.\n\nI want you to fight your way to this meeting and break up the party. Recover whatever you can from the scene and then call for one of us with the flare gun.", sourceObjective = "Slay Chancellor Bloodleaf and Corok the Mighty and recover Illidan's Command.", progress = "What have you to report, soldier?", completion = "So they are attempting to gain the favor of the giants, eh? I have a plan that promises to sever this unholy union.", sourceObjectiveStatus = "unverified-source-field" }
quests[10766] = { id = 10766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion Point: Cataclysm", description = "Now that we have access to the Legion's base at Invasion Point: Cataclysm, we need to figure out a way to shut down their operations there. Wildhammer Stronghold won't be safe until the Legion's presence is erased from Shadowmoon Valley.\n\nI've sent an advance party up to the invasion point to help you formulate a plan to destroy the Legion's supplies. Go back to Legion Hold and step into the teleporter with the green crystals above it. Plexi will meet you at your destination.", sourceObjective = "Report to Plexi at Invasion Point: Cataclysm.", completion = "Pleased to meet you, {name}. Name's Plexi.\n\nI won't bore you with formalities. We both know why we're here. Now, let's get to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[10767] = { id = 10767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion Point: Cataclysm", description = "Now that we have access to the Legion's base at Invasion Point: Cataclysm, we need to figure out a way to shut down their operations there. Shadowmoon Village won't be safe until the Legion's presence is erased from the valley.\n\nI've sent an advance party up to the invasion point to help you formulate a plan to destroy the Legion's supplies. Go back to Legion Hold and step into the teleporter with the green crystals above it. Nakansi will meet you at your destination.", sourceObjective = "Report to Nakansi at Invasion Point: Cataclysm.", completion = "You must be the {race} Blood Guard Gulmok told me to expect. I have a plan in mind, but I'll need your help to complete the preparations.", sourceObjectiveStatus = "unverified-source-field" }
quests[10768] = { id = 10768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabards of the Illidari", description = "The wind riders must return to Shadowmoon Village to prepare for the next phase of our assault. What I need from you now are the tabards that these blood elves wear.\n\nWhen you have collected enough tabards, call for a wind rider using the Kor'kron flare gun. Prepare yourself for a bit of espionage, {race}!", sourceObjective = "Collect 10 Illidari Tabards.", progress = "What have you to report, soldier?", completion = "Ah-ha! These will do quite nicely.", sourceObjectiveStatus = "unverified-source-field" }
quests[10769] = { id = 10769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dissension Amongst the Ranks...", description = "Researcher Tiorus was kind enough to put this concoction together for the final strike. I merely pour it upon this tabard that you have provided for me and the item is imbued with the essence of the Illidari filth.\n\nTake the enchanted tabard and travel to the Eclipsion Fields, southwest of Eclipse Point. Once there, use the tabard to transform into an agent of Illidan. While in disguise, slay the crazed colossi that wander the field. They will think it an attack by the Eclipsion and sever all ties!", sourceObjective = "Slay 5 Crazed Colossus while in disguise as an Illidari blood elf and return to Overlord Or'barokh at Shadowmoon Village in Shadowmoon Valley. He will also want his Kor'kron Flare Gun returned.", progress = "You have returned!", completion = "Well, well, well... If it isn't the grunt I sent out into the field. You're back and in one piece.\n\n<Or'barokh nods.>\n\nI knew you wouldn't let me down, soldier. You've stopped a major Illidari advance and, in doing so, earned yourself a little reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[10770] = { id = 10770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Little Embers", description = "Northeast of here, on the plateau above us lies the burnt ashes of my ancient home. A great wood flourished there before the Burning Legion sent their imps to burn us away. So many died that even centuries later my tired old heart hungers for revenge. There are too many of them for us to ever reclaim the land, but you could make them afraid.\n\nSurely you will help me?", sourceObjective = "Mosswood the Ancient wants you to kill 8 Scorch Imps and then return to him in Ruuan Weald.", progress = "Soon I will sleep the deep sleep of the forest. Before I dig my roots deep and close these old eyes forever, I hope to know that those wretched imps suffered and perished.", completion = "There are so many that we could never kill them all, but you have given me hope. Perhaps I shall try harder for the next few centuries to revive my beloved wood.", sourceObjectiveStatus = "unverified-source-field" }
quests[10771] = { id = 10771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From the Ashes", description = "If you follow the road east and up the side of the mountain, then turn north, you will come to my long lost home.\n\nOnce there was a wood there. Its name is forgotten. Long ago the Burning Legion summoned scorched imps and other creatures of flame. My home was destroyed and my people fled. Now only I remain. \n\nI have saved some ironroot seeds that could be planted in fertile volcanic soil. Their magic is strong. Do this for me and I will share with you the treasures of a forgotten age.", sourceObjective = "Mosswood the Ancient wants you to journey to Skald and plant Ironroot Seeds in three different mounds of Fertile Volcanic Soil and then return to him in Ruuan Weald.", progress = "Is it done?  Did you return some life to my ancient home?", completion = "You destroyed many of those foul little creatures.  I can rest easier in that knowledge.", sourceObjectiveStatus = "unverified-source-field" }
quests[10772] = { id = 10772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of Conquest", description = "My gryphon riders have come back with a bit of news! The Eclipsion blood elves are planning something big. They've begun forming their armies at the Path of Conquest, located east of here - adjacent to Eclipse Point.\n\nI want you to travel to the Path of Conquest and assess the situation. Once you've done so, use this flare gun to signal a gryphon rider. One will swoop down from the sky to meet you. Tell 'em what you've discovered and they'll give you the next set of orders.", sourceObjective = "Travel to the Path of Conquest in Shadowmoon Valley.", progress = "What have you to report, soldier?", completion = "Indeed, these troublesome whelps are up to something insidious. We must investigate further...", sourceObjectiveStatus = "unverified-source-field" }
quests[10773] = { id = 10773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaching the Path", description = "We're going to need more time, {race}. I'm going to fly further ahead with some of the other gryphon riders. Hopefully, we can gather some more information. What I need from you now is to clear a path and more importantly, keep their arrows pointed away from us!\n\nCall for a gryphon rider with the Wildhammer flare gun once you have thinned their numbers.", sourceObjective = "Slay 20 Eclipsion Soldiers, 10 Eclipsion Cavaliers, and 5 Sons of Corok.", progress = "What have you to report, soldier?", completion = "You won't believe this, soldier!", sourceObjectiveStatus = "unverified-source-field" }
quests[10774] = { id = 10774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Elf + Giant = ???", description = "At the southern end of the Path of Conquest, near a stationary caravan, I discovered what looked like a meeting between a giant and a blood elf chancellor. What are giants even doing here? Something is just not right about all of this, grunt.\n\nI want you to fight your way to this meeting and break up the party. Recover whatever you can from the scene and then call for one of us with the flare gun.", sourceObjective = "Slay Chancellor Bloodleaf and Corok the Mighty and recover Illidan's Command.", progress = "What have you to report, soldier?", completion = "So they are attempting to gain the favor of the giants, eh? I have a plan that could serve to sever this unholy union.", sourceObjectiveStatus = "unverified-source-field" }
quests[10775] = { id = 10775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabards of the Illidari", description = "The gryphon riders must return to Wildhammer Stronghold to prepare for the next phase of our assault. What I need from you now are the tabards that these blood elves wear.\n\nWhen you have collected enough tabards, call for a gryphon rider using the Wildhammer flare gun. Prepare yourself for a bit of espionage, {race}!", sourceObjective = "Collect 10 Illidari Tabards.", progress = "What have you to report, soldier?", completion = "Ah-ha! These will do quite nicely.", sourceObjectiveStatus = "unverified-source-field" }
quests[10776] = { id = 10776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dissension Amongst the Ranks...", description = "Gnomus was kind enough to put this concoction together for the final strike. I merely pour it upon this tabard that you have provided for me and the item is imbued with the essence of the Illidari filth.\n\nTake the enchanted tabard and travel to the Eclipsion Fields, southwest of Eclipse Point. Once there, use the tabard to transform into an agent of Illidan. While in disguise, slay the crazed colossi that wander the field. They will think it an attack by the Eclipsion and sever all ties!", sourceObjective = "Slay 5 Crazed Colossus while in disguise as an agent of Illidan and return to Thane Yoregar at Wildhammer Stronghold in Shadowmoon Valley. He will also want his Wildhammer Flare Gun returned.", progress = "You have returned!", completion = "Well, well, well... If it isn't the soldier I sent out into the field. You're back and in one piece.\n\n<Yoregar nods.>\n\nI knew you wouldn't let me down, soldier. You've stopped a major Illidari advance and, in doing so, earned yourself a little reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[10777] = { id = 10777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asghar's Totem", description = "What you read in the commander's journal is true. While the orcish Horde massed under Gul'dan, my people sought to defend ourselves from the threat by striking against him. Gul'dan learned of their intentions and cast a mighty spell that destroyed our camps and twisted the spirits of my brothers.\n\nThey must be stopped before they unleash a greater evil. In the Sketh'lon Wreckage to the north, seek out Asghar and bring me the totem he carries. With it, we can begin to thwart the dark conclave's plans.", sourceObjective = "Bring the Sketh'lon War Totem to Parshah in the Magma Fields.", progress = "Have you recovered the totem from Asghar?", completion = "<Parshah examines the totem.>\n\nGood. This old totem hasn't lost its power over the years, but it alone is not enough to stop the dark conclave.", sourceObjectiveStatus = "unverified-source-field" }
quests[10778] = { id = 10778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rod of Lianthe", description = "The totem alone is not strong enough to counteract the sinister magics of the dark conclave.\n\nWe can combine it with other objects of power, forming a staff to focus the energies. We cannot rescue my brethren from the depths of their depravity, but we can stop them.\n\nOne of the items I need for the staff is the Rod of Lianthe, held by the blood elves at Eclipse Point to the southeast. It is kept in a pavilion on the top tier of the ruins and will be heavily guarded. Use caution, {name}.", sourceObjective = "Obtain Lianthe's Key from any of the blood elves at Eclipse Point and use it to open Lianthe's Strongbox and claim the Rod of Lianthe. Return the rod to Parshah in the Magma Fields.", progress = "Did you manage to get the rod?", completion = "Well done. Such a treasure deserves better than to be shut away in a dark chest. We shall see it used for a worthy purpose.", sourceObjectiveStatus = "unverified-source-field" }
quests[10779] = { id = 10779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Huntress Kella Nightbow at LOCATION. She can put you on the path to earning a pet of your own.", sourceObjective = "Speak with Huntress Kella Nightbow at LOCATION.", sourceObjectiveStatus = "unverified-source-field" }
quests[10780] = { id = 10780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sketh'lon Feathers", description = "There is one last element missing from the staff. We must direct the staff's power toward the Dark Conclave spirits.\n\nWe can do that by gathering feathers scattered on the ground at the Sketh'lon Base Camp and using them in the staff. The base camp is to the south, east of Wildhammer Stronghold.\n\nGul'dan's magic utterly destroyed my brethren, leaving only their spirits, but it did not stop there. The magic fed on the spell the arakkoa were preparing, forging a sinister force that engulfed the spirits.", sourceObjective = "Gather 8 Sketh'lon Feathers and bring them to Parshah in the Magma Fields.", progress = "Have you gathered the feathers for the staff?", completion = "<Parshah accepts the ash-dusted feathers, shaking his head.>\n\nIt would've been better if they had died that day, but nothing is ever that simple. That Gul'dan's magic would turn them into the kind of threat they tried to stop is a particularly cruel twist of fate.", sourceObjectiveStatus = "unverified-source-field" }
quests[10781] = { id = 10781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of the Crimson Watch", description = "They are probably searching for you on the Path of Conquest as we speak. You must make your escape, {race}!\n\nLeave me, I'm done for... They... I think I hear them coming. It's now or never! Get out! If you choose to stay, you will have to fight!\n\nIf you fight and somehow manage to survive, take what you have learned here and deliver that knowledge to A'dal in Shattrath City.", sourceObjective = "Battle the forces of Illidan at Crimson Watch and survive!\n\nReturn to A'dal at Shattrath City should you emerge the victor.", progress = "<A'dal greets you.>", completion = "This Crimson Sigil will be investigated. They pose a threat to all life on Draenor. I foresee a day when their dark master has to answer for his crimes. Perhaps it will be you who brings him to justice, hero.", sourceObjectiveStatus = "unverified-source-field" }
quests[10782] = { id = 10782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imbuing the Headpiece", description = "The staff is nearly finished!\n\nAll that remains is to imbue the headpiece with power flowing from the echoes of Gul'dan in this accursed place. To the east, near the Fel Pits and south of the Deathforge, is the Altar of Damnation.\n\nThere, fragments of Gul'dan's past are trapped. When you carry the unfinished headpiece of the staff into the area around the altar, don't be surprised if some of the entities react to it. You will be carrying a dangerous object with strong connections to the cataclysm.", sourceObjective = "Travel to the Altar of Damnation, and use the Unfinished Headpiece while standing near Gul'dan. When the headpiece is energized, return to Parshah in the Magma Fields.", progress = "Have you returned with the imbued headpiece?", completion = "<Parshah accepts the headpiece, handing it gingerly.>\n\nThis holds the power that we'll need to disrupt the dark conclave's efforts in the Sketh'lon Base Camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[10783] = { id = 10783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Sablemane", description = "Here is my plan. We will poison the ogres and then destroy their gronn master.\n\nDuring my travels in these mountains, I met a man named Baron Sablemane. He is a master of the alchemical arts, and may be convinced to assist us.\n\nYou will find him at the Circle of Blood, down in the canyon to the north of here. Whatever price he requires, I will leave it to your discretion to accept.", sourceObjective = "Speak with Baron Sablemane at the Circle of Blood in the Blade's Edge Mountains.", completion = "Hello, {race}. I am Baron Sablemane. A friend of Rexxar's is a friend of mine.", sourceObjectiveStatus = "unverified-source-field" }
quests[10784] = { id = 10784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crush the Bloodmaul Camp", description = "<Tor'chunk leans in close to whisper.>\n\n{name}, you've done us more than proud in the fight against the ogres so far.  And while I have every confidence in what Rexxar has planned, I would still ask that you crush the ogres at Bloodmaul Camp before returning.\n\nThat way we'll be doubly certain of the outcome.\n\nTo get there, head north down the ramp out of Thunderlord.  Then, at the base of the ramp, head west across Dragons' End and north through the Churning Gulch and Daggermaw Canyon.", sourceObjective = "Slay 10 Bloodmaul Maulers and 5 Bloodmaul Warlocks.", completion = "<Tor'chunk nods his head in obvious approval of your killing prowess.>\n\nYou continue to impress me, {name}.  Every time one of those stinking ogres is felled, we come one step closer to ridding ourselves of an unworthy foe.", sourceObjectiveStatus = "unverified-source-field" }
quests[10785] = { id = 10785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Trap!", description = "There's is no cause of fury greater in this world than that of Gruul and his sons. They slaughtered my people - my children - and now I will have revenge.\n\nI have fashioned a trap from dragon fire, and if you're clever enough, you can use it to kill even a gronn.\n\nJust hurry, take the trap to Rexxar. My thirst for revenge must be quenched.", sourceObjective = "Deliver the Dragonfire Trap to Rexxar at Thunderlord Stronghold in the Blade's Edge Mountains.", progress = "Did you recover whatever was in that gronn's sack for Sablemane? What has he given us?", completion = "Hmm, a trap fashioned from the essence of dragon fire? I wonder how Sablemane comes by such rarified substances?\n\nIt does not matter. What does matter is that we are going to use it to slay a son of Gruul.", sourceObjectiveStatus = "unverified-source-field" }
quests[10786] = { id = 10786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaughter at Boulder'mok", description = "I know that Rexxar has plans for you to head to Boulder'mok.  I have something that I want you to do while you are there.\n\nWe must take any chance we can get to strike down the ogres of these mountains, or they will overrun us, and all that we have bled and died for will be for nothing!\n\nBoulder'mok lies far to the northwest.  Travel north to Ruuan Weald, and from there head west through the tunnel and past the Raven's Wood.\n\n{name}, I want you to kill the Bladespire ogres of Boulder'mok.  Wipe them out!", sourceObjective = "Slay 5 Boulder'mok Brutes and 3 Boulder'mok Shaman, and then return to Tor'chunk Twoclaws at Thunderlord Stronghold in the Blade's Edge Mountains.", completion = "<Tor'chunk grins at the story that you tell him about your adventures at Boulder'mok.>\n\nAh, I wish that I could have been there with you.  Let me tell you something, {name}: never accept any duty that keeps you from the glory of battle!\n\nHah!  After all of the ogre killing that you've done, are there any still left in these mountains for me?!", sourceObjectiveStatus = "unverified-source-field" }
quests[10788] = { id = 10788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Talionia", description = "One of your masters, Talionia, in Silvermoon City has sent a summons for you, {name}.  I'm certain it is time you learned to summon and control a more powerful demon, so I suggest you see her at once.  I understand Talionia is found in The Sanctum, a cozy little den of evil found along Murder Row.", sourceObjective = "Speak with Talionia in Silvermoon City.", completion = "So the world traveler returns...\n\nI hope my sarcasm is evident, {name}, for you have inconvenienced me greatly by forcing me to send out a summons.  Consider that you are but a felguard's hair away from incineration, and they don't have any hair.\n\nPay attention closely, this is not a lesson you'll get twice.", sourceObjectiveStatus = "unverified-source-field" }
quests[10789] = { id = 10789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Carendin Halgar", description = "Ah, so there you are, {name}.\n\nCarendin Halgar has sent out word for you to come see him in the Magic Quarter of Undercity.  He is not known for his patience, so I would not wait long.", sourceObjective = "Speak with Carendin Halgar in Undercity.", completion = "Yes, I can see it in your eye sockets.  You are eager to learn more.\n\nVery well, this is a lesson we'll both enjoy.", sourceObjectiveStatus = "unverified-source-field" }
quests[10790] = { id = 10790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Gan'rul Bloodeye", description = "You are a long way from home, {race}.  Perhaps it is time you returned to learn from your master, Gan'rul Bloodeye.  His knowledge is known to all of our craft, even those of us here.\n\nGan'rul dwells in the Cleft of Shadow in Orgrimmar.", sourceObjective = "Speak with Gan'rul Bloodeye in Orgrimmar.", completion = "It is the forbidden knowledge you hunger for, is it?  I can give you that...", sourceObjectiveStatus = "unverified-source-field" }
quests[10791] = { id = 10791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcoming the Wolf Spirit", description = "I've nearly completed the vestments that I'll wear during the ceremony. As I add the finishing touches, I'd like you to set this incense by the candles near the runestone to my left.\n\nI believe it will help us to attract the wolf spirit's attention, since it was made in the days of the orcish clans. I can almost imagine my ancestors using it in a ceremony paying tribute to the wolf spirit after a successful hunt.\n\nOnce you've placed the incense, I'll begin the ceremony.", sourceObjective = "Use the Ceremonial Incense near the candles in Malukaz's hut and observe the ceremony. When the ceremony is complete, speak with Malukaz again.", progress = "Reestablishing ties with the wolf spirit is just the beginning of my journey, not the end.", completion = "This is incredible! I set out on this journey unsure of whether the wolf spirit would answer our summons and now it feels as though he's always been here. Perhaps he was, {name}.\n\nPerhaps he was waiting for the orcs to realize what their choices had wrought.", sourceObjectiveStatus = "unverified-source-field" }
quests[10792] = { id = 10792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeth'Gor Must Burn!", description = "The Bleeding Hollow clan have betrayed their noble heritage!  We, the orcs who fought and died to save ourselves from the fel taint of Mannoroth, look upon our vile cousins and see only weakness and ignobility... and for that, they must burn!\n\nEnter Zeth'Gor, their bastion to the east, and burn their buildings.  Kill peons for their torches, ignite them at their forge, and hurl the burning torches at their hovels, their stable and their barracks.  Burn them all, and then return to me!\n\nFor the Horde!", sourceObjective = "Kill Bleeding Hollow Peons for their torches, ignite them at Zeth'Gor's forge then throw the burning torches at Zeth'Gor Buildings.", progress = "Zeth'Gor must burn, {name}!  Speak with me again when your task is complete.", completion = "Hah!  I could see the smoke and flames of Zeth'Gor from here!  May the Bleeding Hollow fiends burn to ash and drift far from the sight of any true orc!\n\nThank you, {name}.  You helped burn away an afront to every orc's spirit.", sourceObjectiveStatus = "unverified-source-field" }
quests[10793] = { id = 10793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Journal of Val'zareq: Portends of War", description = "This journal documents the recent activities of Illidan's armies. It also explains why Val'zareq was parading around the Path of Conquest. He was personally responsible for the capture of a high general of the Sha'tar.\n\nThis general is being held at a post known as Crimson Watch, located at the southern end of the Path of Conquest. A mysterious faction, calling itself the Crimson Sigil, is charged with his incarceration. If you choose to investigate, it would be wise to bring allies.", sourceObjective = "Locate Marcus Auralion, High General of the Sha'tar, at Crimson Watch.\n\nLook for him inside a crystalline prison.", progress = "<General Auralion is floating in the middle of the crystal.>\n\nWha... What are you doing here?", completion = "You slew their conqueror? Then we haven't much time...\n\nThe Crimson Sigil is a group comprised of Illidan's elite minions. They are at the top of the chain of command for all Illidari forces outside of the Black Temple. These soldiers communicate directly with the Betrayer here, carrying out his orders without question.\n\nThey are the fiends that will undoubtedly lead an assault on this world, trampling under foot all that would stand in their way.", sourceObjectiveStatus = "unverified-source-field" }
quests[10794] = { id = 10794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rogues of the Shattered Hand", description = "{name}, there are secrets in the world that we do not yet possess.  The Shattered Hand in Orgrimmar can lead you to one of these secrets: the method for brewing deadly poisons.  Do as they ask and you will gain their trust.\n\nTo reach Orgrimmar, take the portal in Silvermoon City to Undercity.  Then, travel outside the city and find the nearby tower where the goblin Zepplins pick up their passengers.  From there, fly to the city of Orgrimmar where you can find Shenthul in the Cleft of Shadow.", sourceObjective = "Speak with Shenthul in Orgrimmar.", completion = "So, you want to work for the Shattered Hand?  Seems like we're getting someone new every day.\n\nPay close attention and I'll explain what you have to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[10795] = { id = 10795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Date with Dorgok", description = "Good, I've seen you around and I've been meaning to speak to you about a matter of some importance.\n\nThere are reports coming in that for some reason the Bloodmaul ogres are planning an offensive against Sylvanaar and Ruuan Weald.  We don't know who or what is pushing them to do this, but I intend to nip their plan in the bud!\n\nBloodmaul Camp is where the attacks are to be staged from.  Head northwest down the ramp out of the Ruuan Weald and you will find it.  I want you to kill their leader, Dorgok!", sourceObjective = "Slay Dorgok at Bloodmaul Camp.", completion = "With Dorgok dead, the Bloodmaul ogres are without leadership, and should be in disarray until another leader arises from within their ranks.\n\nThank you, {class}, I think we can breathe a little easier now.", sourceObjectiveStatus = "unverified-source-field" }
quests[10796] = { id = 10796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crush the Bloodmaul Camp!", description = "I've heard that you've done us more than proud in the fight against the ogres thus far.  Now, I would ask that you face them again.  I want you to crush the ogres at Bloodmaul Camp!\n\nTo get down there, head northwest down the ramp out of the Ruuan Weald.  You'll find them at the base of the ramp.\n\nGood luck, {class}!", sourceObjective = "Slay 10 Bloodmaul Maulers and 5 Bloodmaul Warlocks.", completion = "<The lieutenant nods her head in obvious approval of your killing prowess.>\n\nI am impressed, {name}.  Your reputation seems to be well-deserved.\n\nEvery time one of the ogres is felled, we come one step closer to ridding ourselves of a danger that has no intention of leaving us in peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[10797] = { id = 10797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor of the Gronn", description = "A token in the form of a small statuette falls from Dorgok's dead clutch.  It bears a striking resemblance to one of the gronn.\n\nSurely, Commander Haephus Stonewall at Evergrove in the Ruuan Weald, up the ramp to the east, would be interested in this!", sourceObjective = "Deliver Gorgrom's Favor to Commander Haephus Stonewall at Evergrove in the Blade's Edge Mountains.", progress = "Hello, lad, what news do you bring?", completion = "Oh, now that's pretty.  Looks a lot like those gronn that are always bossing the Bladespire ogres around.\n\nOdd that you should find it in the hands of one of the Bloodmaul leaders.", sourceObjectiveStatus = "unverified-source-field" }
quests[10798] = { id = 10798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pay the Baron a Visit", description = "This is bad news.  Gorgrom the Dragon-Eater is behind the recent Bloodmaul plans against Sylvanaar!\n\nWhy he's manipulating them, and not just using the Bladespire, I don't know.  But if we're to deal with a gronn, we're going to need help.\n\nI know a man who is wise in the ways of all sorts of exotic magics.  Baron Sablemane is his name, and you can find him at the Circle of Blood, back down the ramp to the northwest, and then southwest through the canyon.\n\nAsk him to fashion us a trap for the gronn.", sourceObjective = "Speak with Baron Sablemane at the Circle of Blood in the Blade's Edge Mountains.", completion = "Ah, an envoy from the vaunted Alliance.  Tell me, lackey, why is it that you are here, begging me for this thing, instead of your illustrious commander?\n\nCould it be that he is afraid of me?  It says something about you that you are not, but I haven't quite decided yet what that is.", sourceObjectiveStatus = "unverified-source-field" }
quests[10799] = { id = 10799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Churning Gulch", description = "Very well, I'll create this trap, but first I want something in return.\n\nThere happens to be a nearby gronn that is in possession of an item that I want, but you can't face him, not yet anyway.\n\nSo, you and I are going to fashion a sleeping powder from the poison of the nearby crust bursters.\n\nYou'll find them in the Churning Gulch to the southwest.  Bring me a number of their glands, and be quick about it!", sourceObjective = "Collect 7 Crust Burster Venom Glands.", progress = "You have all of the venom glands?  If not, begone and waste no more of my time until you do!", completion = "Very well.  A simple, if mundane, task has been completed.  Now, hand me the glands and I will perform the difficult part.", sourceObjectiveStatus = "unverified-source-field" }
quests[10800] = { id = 10800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goodnight, Gronn", description = "I've outdone myself again.  I've fashioned a sleeping powder for you to use on Grulloc, the gronn I spoke of who is guarding what I want.\n\nGrulloc keeps himself at the Cursed Hollow, an area at the eastern edge of Dragons' End on the other side of the Circle of Blood.\n\nIf I were you, I wouldn't tarry long once you have his sack.  The effects of the dust won't last long.", sourceObjective = "Collect Grulloc's Sack.", progress = "You are before me again, {class}.  This must mean that you've procured the sack out from underneath Grulloc's nose.", completion = "<Baron Sablemane peers inside the gronn's sack and seems satisfied.>\n\nVery well, you have upheld your end of the bargain.  And now, I will gift your Commander Stonewall with the trap.", sourceObjectiveStatus = "unverified-source-field" }
quests[10801] = { id = 10801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Trap!", description = "There's nothing more that I hate in this world than the sons of Gruul and their father!  They slaughtered my people, and my children, and now I will have a taste of revenge!\n\nI have fashioned a trap from some dragon fire, and if you're clever enough, you might just be able to use it to kill a gronn.\n\nI'm sure that you have a particular gronn in mind; it matters not to me which one you kill.  Just hurry, take the trap to your Commander Stonewall.\n\nMy thirst for revenge must be quenched!", sourceObjective = "Deliver the Dragonfire Trap to Commander Haephus Stonewall at Evergrove in the Blade's Edge Mountains.", progress = "Did the baron fashion us a trap?  One powerful enough to kill a gronn?", completion = "Hmm, a trap fashioned from the essence of dragon flame?  I wonder how Sablemane comes by such rarified substances?\n\nIt does not matter.  What does matter is that we are going to use it to slay a son of Gruul!", sourceObjectiveStatus = "unverified-source-field" }
quests[10802] = { id = 10802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorgrom the Dragon-Eater", description = "We must show the ogres that we are not to be trifled with. We must send a message.\n\nTravel to Boulder'mok and kill the ogres there. Make sure you keep their heads.\n\nThen go to Gorgrom's altar and place the trap there for him. Gorgrom will appear, and you must lure him into the trap. When he is dead, mount your grisly totems near his corpse, so that the ogres may look at their fallen master and their fallen brothers, and know the price for seeking to destroy us.", sourceObjective = "Collect 3 Grisly Totems from Boulder'mok ogres. Then, use Sablemane's Trap at Gorgrom's Altar to summon and kill Gorgrom the Dragon-Eater.\n\nWhen Gorgrom is dead, place the 3 Grisly Totems near his corpse.", progress = "Has the message been delivered?", completion = "Well done, {name}. Well done!\n\nI suspect we will hear little more from the ogres and their master.", sourceObjectiveStatus = "unverified-source-field" }
quests[10803] = { id = 10803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaughter at Boulder'mok", description = "I know that we have plans for you to head to Boulder'mok. I have something that I want you to do while you are there.\n\nWe must take any chance we can get to strike down the ogres of these mountains, or they will overrun us, and all that we have bled and died for will be for nothing!\n\nBoulder'mok lies to the west. Travel southwest, cross the bridge and head through the tunnel. On the west side of the Raven's Wood you will find them.\n\n{name}, I want you to wipe out the Bladespire ogres of Boulder'mok.", sourceObjective = "Slaughter 5 Boulder'mok Brutes and 3 Boulder'mok Shaman.", completion = "<Lieutenant Fairweather grins at the story that you tell her about your adventures at Boulder'mok.>\n\nAh, I wish that I could have been there with you.  Let me tell you something, {name}: never accept any duty that keeps you from the glory of the battlefield!\n\nHah!  After all of the ogre killing that you've done, are there any still left in these mountains for me?!", sourceObjectiveStatus = "unverified-source-field" }
quests[10804] = { id = 10804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kindness", description = "Something has them spooked, {race}.\n\n<Mordenai points to the nether drakes flying overhead.>\n\nThey won't even come down to feed. I have seen several fall to the earth, dead from exhaustion before their bodies hit the ground.\n\nWe must save them! The Rocknail flayers that are found near the crystals are their natural prey. Kill flayers and take their carcasses. Place a carcass in the field and stand extremely still. As long as you do not make any aggressive motions, they will not attack you.", sourceObjective = "Mordenai at Netherwing Fields in Shadowmoon Valley wants you to feed 8 Mature Netherwing Drakes.", progress = "I cannot save them by myself, {name}!", completion = "You are a kind and compassionate {race}, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[10805] = { id = 10805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Massacre at Gruul's Lair", description = "You've proven yourself resourceful, and now I think I'm going to put you to personal use in my own fight against Gruul and his sons.\n\nThe Bladespire clan are the favored of the gronn, and while you may have thinned out their numbers elsewhere, you haven't yet dealt with their strongest.\n\nGruul protects the exterior of his lair with only the toughest of ogres, and it is those that you must kill.  Head north through the Daggermaw Canyon and you will find Gruul's Lair at the end.", sourceObjective = "Slay 10 Bladespire Enforcers, 5 Bladespire Battlemages, 5 Bladespire Ravagers and their leader, Fingrom.", progress = "Have you managed yet to decimate the Bladespire ogres at Gruul's Lair?\n\nDo not come to me with excuses, boy!  Get the job done!", completion = "Very well, I chose wisely when I selected you to spearhead my fight.  Time to ramp things up to a whole new level, I think.\n\nYou remember that little goodie that you stole for me out from underneath Grulloc's nose?  You're going to get a chance to put it to good use.", sourceObjectiveStatus = "unverified-source-field" }
quests[10806] = { id = 10806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Showdown", description = "The time has come for us to face Goc, the master of the Bladespire ogres. It is also time that I take a hand in events, to see the last of the gronn's life.\n\nTake my signet ring. When you come to the Altar of Goc, use it, and I will come to join you.\n\nTogether we will destroy Goc.", sourceObjective = "Use Sablemane's Signet at the Altar of Goc, then kill Goc.", progress = "In time, all the sons of Gruul will be destroyed.", completion = "You fought surprisingly well for a {race}, and it was an honor to have you at my side.  My transformation must have been quite a surprise for you.  I trust it was not too startling?\n\nLet us keep my true identity between the two of us for now, shall we?  In return, and for your adept service, I grant you your choice of any of these baubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[10807] = { id = 10807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ashtongue Broken", description = "The Ashtongue tribe is feared among all Broken.  It consists of the most vicious and bloodthirsty individuals, handpicked by Akama himself.  They are as fierce and ruthless as any naga, demon or blood elf in Illidan's army and they have been deployed in large numbers at the Ruins of Baa'ri, to the north.  Go there and put a dent in their numbers before they get a chance to mount an attack on us.", sourceObjective = "Varen the Reclaimer wants you to go to the Ruins of Baa'ri and slay 3 Ashtongue Handlers, 4 Ashtongue Warriors and 6 Ashtongue Shaman.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", completion = "Glory to the Scryers, {name}.  You've done the Seer's bidding by defeating those who follow Illidan.", sourceObjectiveStatus = "unverified-source-field" }
quests[10808] = { id = 10808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thwart the Dark Conclave", description = "The spirits of the dark conclave seek to summon an ancient and powerful evil through a ritual conducted at the lava pits to the south of the Sketh'lon Base Camp.\n\nGul'dan's magic mingled with their own, empowering them to aid this creature in manifesting in our world! We must not allow this to happen, {name}. The death and destruction it would bring are unimaginable!\n\nCarry the staff with you to the site of the summoning and use its magics to stop the dark conclave once and for all!", sourceObjective = "Slay the Dark Conclave Ritualists and use the Staff of Parshah to end the Dark Conclave's summoning ritual, then return to Parshah in the Magma Fields.", progress = "Is it done, {name}? Have you stopped the dark conclave from completing their ritual?", completion = "I have sought a way to stop the dark conclave for years, and you have succeeded where I failed. The conclave's dark rituals will threaten us no more.\n\nI often feel guilty for abandoning my fellows all those years ago, but now I finally know that I made the right decision. If not for my wavering conscience then, I might have ended up as a shade among them.", sourceObjectiveStatus = "unverified-source-field" }
quests[10809] = { id = 10809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Worg Master Kruush", description = "The poster reads:\n\n\"Worg Master Kruush leads the worg riders of the Bleeding Hollow clan.  A price has been placed on his head, for his riders exact heavy tolls on supply trains to Spinebreaker Post.\"\n\n\"Scouts report him within Zeth'Gor, and the hero able to bring the severed head of this villain to me will earn the thanks of the Horde, and a large bounty.\"\n\n\"-Captain Darkhowl\"", sourceObjective = "Kill Worg Master Kruush and bring his head to Captain Darkhowl in Spinebreaker Post.", progress = "Report, {name}.  Is that Bleeding Hollow blood I see on your sleeve?  I hope so!", completion = "Ah, so you slew that villain, Kruush!  Well done, {name}!  Well done!  His death will defang those cursed worg riders.  In fact, I hope you took a few of them out during your foray into Zeth'Gor!\n\nHere's your reward.  You earned every piece of it!", sourceObjectiveStatus = "unverified-source-field" }
quests[10810] = { id = 10810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Damaged Mask", description = "As you examine the damaged mask, you hear strange sounds coming from within. If the mask wasn't damaged you might be able to hear the sounds more clearly.\n\nO'Mally Zapnabber in Ruuan Weald might be able to fix the mask.", sourceObjective = "Deliver the Damaged Mask to O'Mally Zapnabber at Evergrove in the Blade's Edge Mountains.", progress = "Don't be bothering me! Can't you see I'm trying to unlock mysterious powers?", completion = "Ah, what's that you have? Let me take a closer look, {class}. Yes, yes... it's just what I thought it was. Here, let me fix this mask for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10811] = { id = 10811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Out Neltharaku", description = "Their patron soars high above, {name}. Perhaps the kindness that you showed his children has moved his heart. Seek Neltharaku out and enlist his aid. Together, you may be able to solve the plight of the Netherwing drakes.\n\n<Mordenai points to the sky.>\n\nFly high, friend...", sourceObjective = "Seek out Neltharaku, patron of the Netherwing Dragonflight.", completion = "My children have told me of your heroic deeds, {race}. There is more that you can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[10812] = { id = 10812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery Mask", description = "Ok, it should work now. What is it, you ask? Why, it's a communication device - it allows those blockheads to communicate with each other. You know, the Burning Legion! I would suggest that you hand this mask to Wildlord Antelarion. He's over there pacing around. Always moving, he is.\n\nWell get moving, he's been trying to get his hands on one of these for sometime now.", sourceObjective = "Deliver the Mystery Mask to Wildlord Antelarion at Evergrove in the Blade's Edge Mountains.", progress = "I cannot believe my eyes.", completion = "That mask you hold in your hands is a Felsworn gas mask and by the appearance, it's not damaged. The trouble we can cause Forge Camp: Anger is boundless. Are you interested in helping us out, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[10813] = { id = 10813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eyes of Grillok", description = "{name}, you have braved the lair of the Bleeding Hollow orcs, dreaded Zeth'Gor, and survived!  Perhaps you have the strength to aid me, for I aim to gaze into the mind of its darkest witch, Grillok!\n\nTake this shard.  Use it to ensorcel an Eye of Grillok and bind it to yourself.  Return here and approach my cauldron... and it will pull the eye from you.\n\nGo, {name}.  And use care -- An Eye of Grillok will betray you to our enemies if given the slightest opening!", sourceObjective = "Use Zezzak's Shard to capture an Eye of Grillok, then approach Zezzak's cauldron to extract it. After it is removed, return Zezzak's Shard to him.", progress = "The orcs of the Bleeding Hollow Clan were dark allies long ago... and even darker enemies now.", completion = "I am indebted to you, {name}.  You have again braved Zeth'Gor and held its darkness close to your heart.  I will study the eye and perhaps pierce the secrets of its master, Grillok.\n\nLet us hope that he can no longer use its magic!", sourceObjectiveStatus = "unverified-source-field" }
quests[10814] = { id = 10814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharaku's Tale", description = "I have information that you may find useful. Please listen to what I have to tell you, {race}.", sourceObjective = "Speak with Neltharaku and listen to his story.", progress = "Allow me to finish telling you my tale.", completion = "So you will help us?", sourceObjectiveStatus = "unverified-source-field" }
quests[10815] = { id = 10815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Journal of Val'zareq: Portends of War", description = "This journal documents the recent activities of Illidan's armies. It also explains why Val'zareq was parading around the Path of Conquest. He was personally responsible for the capture of a high general of the Sha'tar.\n\nThis general is being held at a post known as Crimson Watch, located at the southern end of the Path of Conquest. A mysterious faction, calling itself the Crimson Sigil, is charged with his incarceration. If you choose to investigate, it would be wise to bring allies.", sourceObjective = "Locate Marcus Auralion, High General of the Sha'tar, at Crimson Watch.", sourceObjectiveStatus = "unverified-source-field" }
quests[10816] = { id = 10816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming Holy Grounds", description = "You did well against the Broken in Baa'ri, {name}.  Let's see how well you do against Illidan's most feared army.\n\nThe fel orcs of the Shadowmoon Clan occupy the Ata'mal Terrace, once a very holy site where ata'mal crystals were used in spiritual ceremonies.\n\nWe had reason to believe they were hiding an actual ata'mal crystal in the vicinity, but our scrying has revealed nothing.  Nevertheless, the fel orcs are on draenei holy ground and their presence must be dealt with.", sourceObjective = "Vindicator Aluumen wants you to slay 8 Shadowmoon Slayers, 8 Shadowmoon Chosen and 4 Shadowmoon Darkweavers.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", completion = "Excellent work, {class}.  May the Light continue to protect you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10817] = { id = 10817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Retribution", description = "You did well against the Ashtongue Broken, {name}.  I have another challenge for you, should you be up to it.\n\nNot too long ago, the Sanctum of the Stars suffered a tremendous attack by Illidan's fel orcs.\n\nWe've determined it was perpetrated by the Shadowmoon orcs who occupy the Ata'mal Terrace.\n\nShow them that the Scryers are not to be trifled with.", sourceObjective = "Varen the Reclaimer wants you to slay 8 Shadowmoon Slayers, 8 Shadowmoon Chosen and 4 Shadowmoon Darkweavers.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", completion = "You've gained my utmost respect today, {name}.\n\nSlaying one fel orc is not an easy task.  Massacring a score of them is, well... heroic.", sourceObjectiveStatus = "unverified-source-field" }
quests[10818] = { id = 10818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Sablemane Has Requested Your Presence", description = "{name}, while you were out being one hell of a {class}, Baron Sablemane sent his pet dragon up here with a message.\n\nHe's asked for you personally.  From what I understand, he wants you to head up his own fight against the gronn.\n\nI guess you're the most qualified person in all of Outland to help him, but if I were you, I'd get in contact with a couple of friends first and ask them to join you at the Circle of Blood.", sourceObjective = "Speak with Baron Sablemane at the Circle of Blood in the Blade's Edge Mountains.", completion = "Ah, I see that you decided to take your sweet time answering my summons.\n\nNo matter, I have plenty of time to exact my revenge, and I intend for you to be my proxy in the coming battle!", sourceObjectiveStatus = "unverified-source-field" }
quests[10819] = { id = 10819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felsworn Gas Mask", description = "I have a very special mission for you, {name}. I need you to infiltrate Forge Camp: Anger east of here. When you enter the camp you will need to wear the Felsworn gas mask and locate the Legion communicator. Once you have located the communication device speak with whomever is on the other side of the device.\n\nIf all works out you can trick the demon into something devious! Try telling the demon that Camp Anger has revolted.\n\nGood luck to you {class}.", sourceObjective = "Wear the Felsworn Gas Mask and use the Legion Communicator at Forge Camp: Anger in the Blade's Edge Mountains.\n\nProvided item:", completion = "What's the meaning of this! No one summons me! Speak, or I will silence you forever!", sourceObjectiveStatus = "unverified-source-field" }
quests[10820] = { id = 10820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deceive thy Enemy", description = "For every moment I hear silence, you draw closer to your death! SPEAK!\n\nWhat? The camp has revolted? This cannot possibly be true! My minions would not dare undermine my authority.\n\nWell then, every last one of them will pay for this treachery, they will pay dearly. Silence them all and be done with it! Report back to me once you have carried out my order or you shall be dealt with.", sourceObjective = "Slay 4 Doomforge Attendants and 4 Doomforge Engineers.", progress = "My patience is tiring, why have you not finished them?", completion = "That will surely teach those that don't do as I say...\n\nBy the way... where is Doomcryer? Why have you reported this revolt to me and not she?", sourceObjectiveStatus = "unverified-source-field" }
quests[10821] = { id = 10821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You're Fired!", description = "Doomcryer did nothing to stop the revolt? How dare she! She has been trying to undermine my authority for some time. However, this time will be her last. You must summon her and deal with her personally.\n\nHer anger guards hold the keys that summon her to Forge Camp: Anger. Retrieve the five keys and activate the five Legion obelisks. The obelisks have a short duration, so make sure they are all activated at the same time. Remember, the anger guards carry more keys.", sourceObjective = "Slay Doomcryer.", progress = "Are you looking to join my list of those expendable? Get those keys and silence Doomcryer!", completion = "That is great news, great news indeed, {name}. I could not have asked for a better outcome. Your service to our people is most greatly appreciated; choose one of the following heroic items.\n\nYour name will forever be remembered in our peoples' hearts.", sourceObjectiveStatus = "unverified-source-field" }
quests[10822] = { id = 10822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Single Sunfury Signet", progress = "Even the smallest contribution to our cause is noted, {name}.  Our enemies are many, but we shall prevail!", completion = "Victory to the Scryers!  Kael's forces will soon crumble." }
quests[10823] = { id = 10823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Sunfury Signets", progress = "How fares the battle against Kael's forces?", completion = "You're making a name for yourself, {name}.  Keep it up." }
quests[10824] = { id = 10824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunfury Signets", description = "The survival of the Scryers hinges on outrecruiting Kael'thas.  Every pilgrim from Quel'Thalas that joins his side brings him closer to victory.  The opposite is true for us.\n\nSoon, however, we will run out of recruits and it will come down to what side can kill the other quicker.  Prove your worth to the Scryers by bringing me Sunfury signets worn by  high-ranking blood elves allied with Kael'thas and Illidan.  You'll find them at Eclipse Point to the west and the Ruins of Karabor, to the northeast.", sourceObjective = "Battlemage Vyara at the Sanctum of the Stars wants you to bring her 10 Sunfury Signets.\n\nPerforming quests for the Scryers will cause you Aldor reputation level to decrease.", progress = "Go on, {name}.  Speak.", completion = "Kael's elves are extremely well-trained.  Excellent job.", sourceObjectiveStatus = "unverified-source-field" }
quests[10825] = { id = 10825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Truth Unorbed", description = "This strange, magical orb drops from beneath the contour feathers of the arakkoa.\n\nSuffused with an eerie, purple glow, the orb pulses to an unheard beat.  Holding it makes you mildly uncomfortable, and so you quickly place it within your pack.\n\nPerhaps Tree Warden Chawn at Ruuan Weald to the west, through the tunnel and across the Wyrmskull Bridge, would be interested in examining it?", sourceObjective = "Deliver the Orb of the Grishna to Tree Warden Chawn at Evergrove in the Blade's Edge Mountains.", progress = "{class}, do you feel that?  I sense something unnatural and evil nearby.", completion = "Yes, it's that orb you have there!  Odd, it appears to be of arakkoan design.  Were you recently at Grishnath?\n\nAll right, that explains that, but I wonder what diabolical purpose this object serves.  Though it radiates evil, it also somehow feels as if it were connected to the natural world.\n\nHere, allow me to try activate it.  The evil is so strong within it, there's some sort of residual memory here....", sourceObjectiveStatus = "unverified-source-field" }
quests[10826] = { id = 10826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marks of Sargeras", description = "By now it should be clear to you why we oppose the Burning Legion and those who serve them.\n\nIf you wish to prove yourself to the Aldor, bring me the insignias of high-ranking Legion and their Shadow Council followers.  Here in Shadowmoon you will find a strong Legion presence to the far west in Legion Hold and the Deathforge.", sourceObjective = "Bring 10 Marks of Sargeras to Harbinger Saronen in Shadowmoon Valley.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Do you bear any of our enemies' insignias, {name}?", completion = "Your courage is strong, friend.  Let it be known to all that you are a true ally of the priesthood!", sourceObjectiveStatus = "unverified-source-field" }
quests[10827] = { id = 10827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Marks of Sargeras", progress = "Do you bear more of our enemies' insignias, {class}?  We will fight the Legion until the Light prevails.", completion = "Destroy the enemies of the Light wherever you find them, {name}." }
quests[10828] = { id = 10828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Single Mark of Sargeras", progress = "I'll take any leftover marks you might have.  Do not worry; your actions will be duly noted.", completion = "You continue to prove your worth, {name}." }
quests[10829] = { id = 10829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treebole Must Know", description = "This is troubling!  The arakkoa are causing the ancients and protectors to become possessed by evil spirits!\n\nBut, there is one ancient that could not possibly have been affected.  His name is Treebole, and you must go to him at once if we're to save the trees of the Raven's Wood!\n\nGo back to the Raven's Wood.  You will find him at the fork in the path just past Grishnath.", sourceObjective = "Speak with Treebole, an ancient of lore who lives in the Raven's Wood of the Blade's Edge Mountains.", completion = "Greetings, tiny {race}.  The birds in my boughs whispered to me that you were to be expected.\n\nYou are here to help free the trees of the woods from their possession?", sourceObjectiveStatus = "unverified-source-field" }
quests[10830] = { id = 10830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exorcising the Trees", description = "The Grishna have caused the leafbeards and stonebarks to be inhabited by evil koi-koi spirits.\n\nWe must save the trees or soon all of the Raven's Wood will be lost forever!\n\nCombine the magic of a Grishnath orb, found throughout Grishnath, with a dire pinfeather from a dire raven.\n\nUse the resultant exorcism feather to draw out and slay the koi-koi spirit as quickly as possible.  The stonebarks are too powerful for this ritual, but if enough leafbeards are saved, they will be freed as well.", sourceObjective = "Collect 5 Grishnath Orbs and 5 Dire Pinfeathers and then combine them into Exorcism Feathers. Use these feathers to exorcise and slay 5 Koi-Koi Spirits from the Raven's Wood Leafbeards.", progress = "The evil that is inhabiting the trees is beginning to seep into every natural thing in the woods.\n\nYou must act quickly, {name}, before all is lost!", completion = "The evil is lifting from the Raven's Wood!  Can you feel it, {name}?\n\nYou have saved us, and all of the surrounding wildlife, from certain destruction, little one!\n\nI keep stashed four magic rings amongst my boughs for such occasions as this, when a hero arises to do some great deed.\n\nYou are one such hero!  On behalf of all of the Raven's Wood, we give you thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[10831] = { id = 10831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Becoming a Mooncloth Tailor", description = "I can teach you the ways of mooncloth tailoring, if you are interested.. By specializing in mooncloth tailoring, creating primal mooncloth will yield twice the normal amount and you will have access to several exclusive patterns. All that is required is that you pass a simple test.\n\nAs to the test, your task is to create a small sample of primal mooncloth in the moonwell at Cenarion Refuge. I will provide all the materials you'll need. When you've created the sample, bring it back to me for examination.", sourceObjective = "Use the Square of Imbued Netherweave while standing in Cenarion Refuge's moonwell to create a Sample of Primal Mooncloth. Bring the completed sample back to Nasmara Moonsong in Shattrath's Lower City.\n\n*WARNING!* You can only select one tailoring specialization.", progress = "Have you created the primal mooncloth sample?", completion = "<Nasmara examines the cloth, turning it over in her hands.>\n\nThis is an exceedingly fine sample, {name}. You will make an excellent mooncloth tailor.", sourceObjectiveStatus = "unverified-source-field" }
quests[10832] = { id = 10832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Becoming a Spellfire Tailor", description = "I can teach you the ways of spellfire tailoring if you wish, but be warned, it's a dangerous pursuit.\n\nCreating spellcloth in Netherstorm attracts powerful nether-wraiths. I'm searching for a way to lessen backlash, but I need more nether-wraith essence for my research.\n\nTake this beacon with you to Netherstorm and use it to summon a nether-wraith. Bring back its essence and I'll agree to teach you. As a spellfire tailor, you'll receive twice as much cloth and have access to exclusive patterns.", sourceObjective = "Bring a sample of Nether-wraith Essence to Gidge Spellweaver in Shattrath's Lower City.\n\n*WARNING!* You can only select one tailoring specialization.", progress = "Did you get the nether-wraith sample?", completion = "<Gidge examines the nether-wraith essence.>\n\nEven this small a sample of the creature's essence radiates power. Perhaps I misunderstood what's happening. We're not angering the wraiths by taking energy from the environment. Rather, the wraiths and the environment are the same thing!\n\nDon't hesitate to let me know if you make any further discoveries, now that you've become a spellfire tailor.", sourceObjectiveStatus = "unverified-source-field" }
quests[10833] = { id = 10833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Becoming a Shadoweave Tailor", description = "If you become a shadoweave specialist, you will make twice as much shadowcloth as an average tailor and have access to several exclusive patterns.\n\nOf course, any tailor can use the Altar of Shadows, but a shadoweave tailor possesses a deeper attunement to the altar, unlocking powers that few can fathom.\n\nTake this crystal to eastern Shadowmoon Valley, and find Netherwing Pass leading south from the Netherwing Fields. Near the world's edge, you will find the Altar of Shadows. Use the crystal there.", sourceObjective = "Use the Crystal of Deep Shadows near the Altar of Shadows to deepen your attunement to the altar, then return to Andrion Darkspinner in Shattrath's Lower City.\n\n*WARNING!* You can only select one tailoring specialization.", progress = "Have you used the crystal's power to deepen your attunement to the Altar of Shadows?", completion = "I can see that your visit to the altar was a success. There is a subtle difference about you that few will see, but there's no doubt it's there.", sourceObjectiveStatus = "unverified-source-field" }
quests[10834] = { id = 10834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grillok \"Darkeye\"", description = "Grillok Darkeye has wagered a piece of himself to dark powers, and gained great magic for it.  His lost eye burns deep in some hellish pit, now a demon's trinket... and the patch that covers his betrayal holds its own dark secrets.\n\nBring me Grillok's eyepatch, {name}, and I will reward you greatly for your service...", sourceObjective = "Kill Grillok Darkeye and bring Grillok's Eyepatch to Zezzak in Spinebreaker Post.", progress = "The evils of the Bleeding Hollow orcs know no bounds, and are rivaled by only their Shattered Hand cousins.", completion = "Ah, yes.  Just as some who lost a hand or a leg in battle will oftentimes feel their severed limb, I wonder if Grillok still clutched at his lost eye in his dark, dark dreams...\n\nI too will dream on this, and if fortune is with us then perhaps I will learn what drew Grillok and the Bleeding Hollow orcs to succumb to demons.", sourceObjectiveStatus = "unverified-source-field" }
quests[10835] = { id = 10835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apothecary Antonivich", description = "{name}, I have prepared a preliminary report of my findings regarding the Bleeding Hollow orcs.  My colleague in Thrallmar, Apothecary Antonivich, will be happy to receive them.  He too studies the phenomenon of fel orcs... in hopes of preventing such a tragedy from again befalling our orcish allies.\n\nTake him this report, and I will continue my study of the blood you brought me.  If fortune is with us, we will isolate the cause of the fel orc affliction.", sourceObjective = "Bring Albreck's Findings to Apothecary Antonivich at Thrallmar in Hellfire Peninsula.", progress = "Good day, {name}.  And how is your stay in Hellfire Peninsula?  I trust it has been fruitful...", completion = "Ah, a report from Albreck?  Very good.  The Royal Apothecary Society works feverishly to determine how the orcs of Hellfire Peninsula became fel orcs.  Their betrayal is unforgivable... and we must ensure that our orc friends are forever safe from future corruption.", sourceObjectiveStatus = "unverified-source-field" }
quests[10836] = { id = 10836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating Dragonmaw Fortress", description = "I require time so that I may devise a plan to save my children and mate. You will buy me this time, mortal.\n\nVenture into Dragonmaw Fortress, located on the eastern edge of the Netherwing Fields, and lay waste to all Dragonmaw orcs that you find. The ensuing chaos and confusion should have a considerable impact on their plans.\n\nBe warned, some of my kin are too far gone - their minds corrupted by the Dragonmaw. For them, the only resolution is death. You have my permission to end their lives as well.", sourceObjective = "Neltharaku, flying high above Netherwing Fields in Shadowmoon Valley, wants you to slay 15 Dragonmaw Orcs.\n\nAny Dragonmaw Orc in Dragonmaw Fortress will suffice.", progress = "Is it done? I can only hope that it is not too late...", completion = "Well done, {name}. I have discovered a way in which we can free the enslaved drakes that are being held at Dragonmaw Fortress.", sourceObjectiveStatus = "unverified-source-field" }
quests[10837] = { id = 10837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Netherwing Ledge!", description = "I believe that I can imbue nethervine crystals with my own essence. The power contained within these imbued crystals should be sufficient to free enslaved drakes of their masters' grasps.\n\nTravel to Netherwing Ledge, an island located off the broken shelf of Shadowmoon Valley, to the southeast. It is on Netherwing Ledge that you will find nethervine crystals. Return to me when you have collected enough crystals to fill your packs.\n\nAnd {name}, Beware the Dragonmaw that now inhabit the island.", sourceObjective = "Neltharaku, flying high above Netherwing Fields in Shadowmoon Valley, wants you to collect 12 Nethervine Crystals from Netherwing Ledge.", progress = "I require nethervine crystals.", completion = "<Neltharaku takes the crystals from you.>\n\nI will prepare the crystals for you now.", sourceObjectiveStatus = "unverified-source-field" }
quests[10838] = { id = 10838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Demoniac Scryer", description = "The Demoniac Scryer is now ready.  Take it behind Hellfire Citadel, to Hellfire Basin, and summon it upon the ground.  It will then begin to attune itself to Hellfire Citadel.  After its attunement, speak to the Scryer and transcribe what it tells you.  Bring that transcription to me...\n\nGo, {name}, but only when you are ready.  There is no doubt that Hellfire Citadel will detect the Scryer and send wardens to destroy it!", sourceObjective = "Use the Demoniac Scryer in Hellfire Basin, wait for it to attune, and then take a reading.\n\nReturn the Demoniac Scryer and the Demoniac Scryer Reading to Apothecary Antonivich in Thrallmar.", progress = "Do you have the reading?  Has your mission with the Demoniac Scryer been successful?", completion = "You obtained the reading?  Excellent -- I am sure this data will prove invaluable to our research.  I will disseminate it to Apothecaries Zelana and Albreck.\n\nYou should be proud, {name}.  Your strength and bravery is unquestionable... as is your service to the Horde.", sourceObjectiveStatus = "unverified-source-field" }
